local config = {
  ui_story_5058_50580101_1_dialog_content = "\"How are you, old friend? I haven't heard from you in a long time.\"",
  ui_story_5058_50580101_2_dialog_content = "\"I'm still the same. As you know, we mercenaries get a lot of weird assignments.\"",
  ui_story_5058_50580101_3_dialog_content = "\"Not much free time on my hands, but just being able to paint a couple of strokes a day is enough for me.\"",
  ui_story_5058_50580101_4_dialog_content = "\"It's just that I haven't been able to meet anyone else who shares my interest in insects like you do.\"",
  ui_story_5058_50580101_X4_dialog_content = "\"That makes me feel somewhat lonely.\"",
  ui_story_5058_50580101_5_dialog_content = "\"However, I have made new friends, such as PlayerName.\"",
  ui_story_5058_50580101_X5_dialog_content = "\"I'll introduce you two when I get a chance.\"",
  ui_story_5058_50580101_6_dialog_content = "\"But I digress. I've heard word on the butterfly dubbed the <color=#FFB400>Denuo Goddess</color> lately.\"",
  ui_story_5058_50580101_7_dialog_content = "\"A place called the <color=#FFB400>Denuo Valley Resort</color> advertised that the stunning butterfly could be seen there...\"",
  ui_story_5058_50580101_8_dialog_content = "\"It also claimed that catching sight of one would bring good luck and the goddess' blessings.\"",
  ui_story_5058_50580101_9_dialog_content = "\"Of course it's obviously pure hype, but I remembered you mentioning this butterfly species.\"",
  ui_story_5058_50580101_10_dialog_content = "\"Even though you never divulged to me the connection between them and your inscrutable hometown...\"",
  ui_story_5058_50580101_11_dialog_content = "\"Regardless, I hope the news is helpful to you, and we have a chance to meet again.\"",
  ui_story_5058_50580101_12_dialog_content = "\"Looking forward to your reply.\"",
  ui_story_5058_50580101_13_dialog_content = "I can't believe anyone would miss someone like me.",
  ui_story_5058_50580101_14_dialog_content = "But how am I going to explain to you what I'm doing now, Luke...?",
  ui_story_5058_50580101_15_dialog_content = "Mind coming over for a minute, Cena?",
  ui_story_5058_50580101_16_dialog_content = "The <color=#FFB400>invitation</color> I mentioned is done. Please send it out for me!",
  ui_story_5058_50580101_17_dialog_content = "Sure, boss, will do!",
  ui_story_5058_50580101_18_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5058_50580101_19_dialog_content = "Are you sure we're at the right place, PlayerName? I don't even see anything resembling a normal house...",
  ui_story_5058_50580101_20_dialog_content = "It just doesn't scream \"the premium resort to see the Denuo Goddess!\" to me.",
  ui_story_5058_50580101_21_dialog_content = "Well, this is where the coordinates pointed to...",
  ui_story_5058_50580101_22_dialog_content = "Did you buy the tickets through legit channels?",
  ui_story_5058_50580101_23_option_content = "I made sure of that!",
  ui_story_5058_50580101_24_dialog_content = "Then what's with that <color=#FFB400>invitation</color> you're holding?",
  ui_story_5058_50580101_25_dialog_content = "The resort sent it to me, so it should be legit, right?",
  ui_story_5058_50580101_26_option_content = "Well...",
  ui_story_5058_50580101_27_dialog_content = "I got this <color=#FFB400>invitation</color> for me in mail, so it should be legit, right?",
  ui_story_5058_50580101_28_dialog_content = "Huh? Let me see...",
  ui_story_5058_50580101_29_dialog_content = "\"Esteemed PlayerName, we're pleased to announce the much-anticipated Denuo Valley Resort is finally completed!\"",
  ui_story_5058_50580101_30_dialog_content = "\"The premises include a huge amusement park and a premium hotel.\"",
  ui_story_5058_50580101_31_dialog_content = "\"We sincerely invite you to experience all the amenities and services we have to offer on the house, before we open to the public!\"",
  ui_story_5058_50580101_32_dialog_content = "\"Enclosed with this invitation are three VIP passes. Please feel free to bring along family or friends.\"",
  ui_story_5058_50580101_33_dialog_content = "\"The entire Denuo Valley Resort staff awaits your arrival!\"",
  ui_story_5058_50580101_34_dialog_content = "\"Principal Owner: Lorelei Cardogon\"?",
  ui_story_5058_50580101_35_dialog_content = "I was wondering why you would have tickets to an unopened resort, PlayerName.",
  ui_story_5058_50580101_36_dialog_content = "So they were actually free passes... I thought you dug into your savings.",
  ui_story_5058_50580101_37_dialog_content = "But this sounds too good to be true. I think it's one of those newer scams, or...",
  ui_story_5058_50580101_38_dialog_content = "Wait, what if there are bandits lying in wait to ambush us?",
  ui_story_5058_50580101_39_dialog_content = "Hey, hold on. Isn't this Rediesel Wrench territory?",
  ui_story_5058_50580101_40_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5058_50580101_41_dialog_content = "We're actually getting bandits for real?!",
  ui_story_5058_50580101_42_dialog_content = "Bandits? Well, you're absolutely right in the sense that a bandit is present to steal ladies' hearts... but that's not the point.",
  ui_story_5058_50580101_43_dialog_content = "We've been looking forward to your visit, PlayerName, and finally, here you are today.",
  ui_story_5058_50580101_44_dialog_content = "The lovely young ladies with you must be Vice and Carleen, I presume?",
  ui_story_5058_50580101_45_dialog_content = "Who are you?",
  ui_story_5058_50580101_46_dialog_content = "Apologies for not having properly introduced myself. I am Cena, <color=#FFB400>general manager</color> of the Denuo Valley Resort.",
  ui_story_5058_50580101_47_dialog_content = "Oh, thank heavens, the passes were legit! But is this place really a resort? It doesn't quite match the description in the pamphlet...",
  ui_story_5058_50580101_48_dialog_content = "Hahaha, Denuo Valley can be rather treacherous even for Eclipsites. It's not an easy place to find.",
  ui_story_5058_50580101_49_dialog_content = "Even though we set up shuttles for our guests from all four corners of the world...",
  ui_story_5058_50580101_50_dialog_content = "The boss specifically instructed me to pick you up personally, since you're our premier VIP.",
  ui_story_5058_50580101_X50_dialog_content = "Does our honored guest have any questions?",
  ui_story_5058_50580101_51_option_content = "The boss?",
  ui_story_5058_50580101_52_dialog_content = "Is that the Ms. Lorelei Cardogon on the invitation?",
  ui_story_5058_50580101_53_dialog_content = "Yes. Miss Lorelei is the eldest daughter of the Cardogon family and real estate fame, as well as the principal owner of Denuo Valley Resort.",
  ui_story_5058_50580101_54_dialog_content = "It takes someone impressive to build a giant resort, yet this is the first time I've heard this name.",
  ui_story_5058_50580101_55_dialog_content = "Which isn't unusual, actually. The Cardogons are low-key, but have investments throughout Astra. Their name is usually only known to business insiders.",
  ui_story_5058_50580101_56_dialog_content = "But Miss Lorelei didn't rely on her family for this venture. She recruited outside investments herself to launch the facility.",
  ui_story_5058_50580101_57_dialog_content = "She completes all this independently of her family? That's gutsy!",
  ui_story_5058_50580101_X57_dialog_content = "Exactly.",
  ui_story_5058_50580101_58_option_content = "I'm a premier VIP?",
  ui_story_5058_50580101_X59_dialog_content = "That's a stretch...",
  ui_story_5058_50580101_59_dialog_content = "PlayerName, your reputation is known all throughout Astra and has even spread to the far east.",
  ui_story_5058_50580101_60_dialog_content = "The boss has been a fan of yours... No, what's the word again?",
  ui_story_5058_50580101_61_dialog_content = "Ah, got it, a Lovegator!",
  ui_story_5058_50580101_62_dialog_content = "I'm flattered! But your boss sure has a broad perspective even to know such things.",
  ui_story_5058_50580101_X61_dialog_content = "Indeed!",
  ui_story_5058_50580101_X62_dialog_content = "Oh, you also mentioned...",
  ui_story_5058_50580101_63_option_content = "A shuttle?",
  ui_story_5058_50580101_64_dialog_content = "That means we have to take a ride... Is the resort far from here?",
  ui_story_5058_50580101_65_dialog_content = "I wouldn't say far, but getting there could be a bit adventurous. Just be ready. I guess you could call the trip a thrill ride too.",
  ui_story_5058_50580101_66_dialog_content = "We're not racing a hundred-mile-per-hour over this arid, desolate place again, are we? Where are the waterfalls and lakes? Where's the cool summer vacation I craved?",
  ui_story_5058_50580101_67_dialog_content = "Everything you're looking for is in Denuo Valley. Since you're chomping at the bit to get there, get in the shuttle already!",
  ui_story_5058_50580101_68_dialog_content = "The sooner we get there, the sooner we can start having fun, am I right?",
  ui_story_5058_50580101_69_dialog_content = "Oh come on, don't look like you're gonna hurl before you even get in the car! Just so you know, everyone likes my driving.",
  ui_story_5058_50580101_70_dialog_content = "Oh, one more thing... Look this way, honored guests, and say, \"Cheese!\"",
  ui_story_5058_50580101_71_dialog_content = "Huh?",
  ui_story_5058_50580101_72_dialog_content = "You gotta take pictures to remember the vacation by!",
  ui_story_5058_50580101_73_dialog_content = "That's so thoughtful... I have a feeling we'll have a great time here!",
  ui_story_5058_50580101_74_dialog_content = "I hope so.",
  ui_story_5058_50580101_75_dialog_content = "Hey, Carleen, don't give me that look! Nothing will go wrong this time, right? Hey!",
  ui_story_5058_50580101_76_dialog_content = "<color=#e8d9bb>Creak...</color>",
  ui_story_5058_50580101_77_dialog_content = "We're here, everyone. Please exit the vehicle.",
  ui_story_5058_50580101_78_dialog_content = "Uh... was... was that your aforementioned \"great driving\"?",
  ui_story_5058_50580101_79_dialog_content = "La-la-la, la-ta-ta-la-la... ♪",
  ui_story_5058_50580101_80_dialog_content = "What's that?",
  ui_story_5058_50580101_81_dialog_content = "La-la-la, la-ta-ta-la-la ♪ The Denuo Valley Resort welcomes you ♪",
  ui_story_5058_50580101_82_dialog_content = "Wow, it's the same as the picture in the pamphlet!",
  ui_story_5058_50580101_83_dialog_content = "We were just in a barren desert and now it's so vibrant all around... It's like we're in a different world.",
  ui_story_5058_50580101_84_dialog_content = "Big thanks to all of you awesome folks for picking Denuo Valley Resort to begin your fantastic holiday! Get ready for non-stop fun and epic adventures!",
  ui_story_5058_50580101_85_dialog_content = "Yes, exactly, non-stop fun and epic adventures! But that still sounds so bare bones!",
  ui_story_5058_50580101_86_dialog_content = "\"In addition, we shall offer the most premier services and sumptuous feasts?\"",
  ui_story_5058_50580101_87_dialog_content = "Hmm. Cena, remind the publicity folks to work on the entrance slogan.",
  ui_story_5058_50580101_88_dialog_content = "Got it, Miss Lorelei.",
  ui_story_5058_50580101_89_dialog_content = "Miss Lorelei? So you're Miss Lorelei Cardogon, the owner?",
  ui_story_5058_50580101_90_dialog_content = "<size=45>PlayerName, you're here at last!</size>",
  ui_story_5058_50580101_91_dialog_content = "Wow, that's a lovely tail! You must be Vice.",
  ui_story_5058_50580101_92_dialog_content = "And the ethereal young lady here must be Carleen!",
  ui_story_5058_50580101_93_dialog_content = "Glad I had the foresight to include three passes. I had a hunch you would bring them both, PlayerName!",
  ui_story_5058_50580101_94_dialog_content = "I'm grateful for you to take time out of your busy schedule to attend our soft opening.",
  ui_story_5058_50580101_95_dialog_content = "Please make yourselves at home. Enjoy and knock yourselves out!",
  ui_story_5058_50580101_96_dialog_content = "Well, thank you for inviting us, Miss Lorelei. I've never been to a park as magnificent as this!",
  ui_story_5058_50580101_97_dialog_content = "Please, just call me Lorelei.",
  ui_story_5058_50580101_98_dialog_content = "Hmm, Teeny's supposed to show you around... Where is she?",
  ui_story_5058_50580101_99_dialog_content = "Anyway, please come in!",
  ui_story_5058_50580101_100_dialog_content = "...",
  ui_story_5058_50580101_101_dialog_content = "Hey, that red-headed girl over there...",
  ui_story_5058_50580101_102_option_content = "I think I know her!",
  ui_story_5058_50580101_103_dialog_content = "Isn't that Bopper?",
  ui_story_5058_50580101_104_dialog_content = "PlayerName... Of course. No one but you would notice me right off the bat...",
  ui_story_5058_50580101_105_option_content = "She looks familiar.",
  ui_story_5058_50580101_106_dialog_content = "I knew it... I guess it's been too long for you to remember me.",
  ui_story_5058_50580101_107_dialog_content = "I'm Bopper, PlayerName. You have the giant birdie, and I have my Giant Lizard!",
  ui_story_5058_50580101_108_dialog_content = "Bopper, from the Rediesel Wrench?!",
  ui_story_5058_50580101_109_dialog_content = "There you are, Teeny. I've been looking hard for you!",
  ui_story_5058_50580101_110_dialog_content = "But I've been by your side the whole time, Miss Lorelei...",
  ui_story_5058_50580101_111_dialog_content = "Are you here for the soft opening too, Bopper?",
  ui_story_5058_50580101_112_dialog_content = "She's the technical specialist I specifically requested from the Rediesel Wrench!",
  ui_story_5058_50580101_113_dialog_content = "Well, I'm actually more of a general mechanic than the expert Miss Lorelei makes me out to be... Other Rediesel Wrench guys are here to help too.",
  ui_story_5058_50580101_114_dialog_content = "Rediesel Wrench people are working regular jobs now? This could be my chance to catch some of those wanted fugitives.",
  ui_story_5058_50580101_115_dialog_content = "Uh, Carleen, let's not dwell on that on our vacation, okay?",
  ui_story_5058_50580101_116_dialog_content = "Our resort personnel have gone through extensive background checks and training. We'll take care of any issues that should arise without you having to lift a finger.",
  ui_story_5058_50580101_117_dialog_content = "Sorry to interrupt, sir. Three customers out there are specifically asking to see you...",
  ui_story_5058_50580101_118_dialog_content = "I believe I'm done here, Miss Lorelei. I'm off to take care of other business.",
  ui_story_5058_50580101_119_dialog_content = "PlayerName, Miss Vice, and Miss Carleen, I wish you all a fun stay in advance!",
  ui_story_5058_50580101_120_dialog_content = "Don't tell me another bevy of pretty ladies just showed up? I just don't know what to do with him...",
  ui_story_5058_50580101_121_dialog_content = "Though I can't believe the time... Why did the meeting have to be scheduled for now?",
  ui_story_5058_50580101_122_dialog_content = "Well, folks, I'm glad to have you all here!",
  ui_story_5058_50580101_123_dialog_content = "But I've gotta run now. When I'm done, I'll check you into the hotel and show you the attractions!",
  ui_story_5058_50580101_124_dialog_content = "You can take it from here, Teeny!",
  ui_story_5058_50580101_125_dialog_content = "Ahem... just call me Bopper...",
  ui_story_5058_50580101_126_dialog_content = "Knowing that you were coming, I stayed up all night and drafted thirty-three itineraries.",
  ui_story_5058_50580101_127_dialog_content = "I combined PlayerName, Vice, and Carleen's personal preferences to derive the best steps and route...",
  ui_story_5058_50580101_128_dialog_content = "Uh, you don't have to be that thorough, Bopper. We can just take it easy.",
  ui_story_5058_50580101_129_dialog_content = "Take it easy? Fortunately, I also have a plan for that.",
  ui_story_5058_50580101_130_dialog_content = "Okay, then. Follow me, everyone.",
  ui_story_5058_50580101_131_dialog_content = "We're about to embark on the most casual itinerary planned!",
  ui_story_5058_50580201_1_dialog_content = "These are the pictures PlayerName the Caelestite took on the way to the resort.",
  ui_story_5058_50580201_2_dialog_content = "We'll also photograph the Caelestite with the various attractions and hotel amenities.",
  ui_story_5058_50580201_3_dialog_content = "Then we can put a full-length feature in your publication!",
  ui_story_5058_50580201_4_dialog_content = "That will both sell the issue and increase exposure for the resort.",
  ui_story_5058_50580201_5_dialog_content = "Hmm... I have to admit Lovegators do have some purchasing power.",
  ui_story_5058_50580201_6_dialog_content = "Based on our findings, places the Caelestite visits tend to go viral, like Cloud Island, Harbor City...",
  ui_story_5058_50580201_7_dialog_content = "Even a place like Euphoria boomed!",
  ui_story_5058_50580201_8_dialog_content = "True, Harbor City is now the most popular tourist destination in Astra.",
  ui_story_5058_50580201_9_dialog_content = "Harbor City? Why does that sound familiar?",
  ui_story_5058_50580201_10_dialog_content = "You, on a mission, decided to join a competition midway and almost ended up falling into the water.",
  ui_story_5058_50580201_11_dialog_content = "AHHH! Memories of those reckless commoners rushing around come flooding back! Shut up! SHUT UP!",
  ui_story_5058_50580201_12_dialog_content = "Lorelei, I'm glad you took our advice and used the Denuo Goddess as the resort's breakthrough in marketing.",
  ui_story_5058_50580201_13_dialog_content = "And I really appreciate your idea of leveraging the Caelestite's fame for promotion.",
  ui_story_5058_50580201_14_dialog_content = "But honestly, these are all temporary marketing strategies, and they might not hold up in the long haul.",
  ui_story_5058_50580201_15_dialog_content = "We're all aware that the Denuo Goddess is merely a tale. Who knows if it even exists?",
  ui_story_5058_50580201_16_dialog_content = "Not to mention, the popularity of the Caelestite might not last, and it could turn into a major headache someday.",
  ui_story_5058_50580201_17_dialog_content = "The money we've poured into the resort is no trifling sum...",
  ui_story_5058_50580201_18_dialog_content = "I get what all of you want as investors.",
  ui_story_5058_50580201_19_dialog_content = "To make the resort a sustainable operation, we must ensure quality services and provide—",
  ui_story_5058_50580201_20_dialog_content = "No, what I mean is we should provide something more \"addictive\"...",
  ui_story_5058_50580201_21_dialog_content = "...",
  ui_story_5058_50580201_22_dialog_content = "Are you sure this is your most casual itinerary, Bopper?",
  ui_story_5058_50580201_23_dialog_content = "Yes... This is the route I take when I want to relax, myself.",
  ui_story_5058_50580201_24_dialog_content = "Does this really relax you?!",
  ui_story_5058_50580201_25_dialog_content = "Death's Door is my favorite ride. Some people in Rediesel Wrench could ride it a dozen times a day!",
  ui_story_5058_50580201_26_dialog_content = "We're lucky you got here early. We'd have to wait in a long line otherwise.",
  ui_story_5058_50580201_27_dialog_content = "Whoa, I can hardly wait! Hurry up, PlayerName.",
  ui_story_5058_50580201_28_dialog_content = "I think my knees are buckling already...",
  ui_story_5058_50580201_29_dialog_content = "What? I thought you'd be used to this height with how often you pilot the Giant Eagle...",
  ui_story_5058_50580201_30_dialog_content = "She has a point. You've even experienced crashing several times, so this should be child's play by now.",
  ui_story_5058_50580201_31_dialog_content = "Doing something like this actively versus having no choice is entirely different...",
  ui_story_5058_50580201_32_dialog_content = "Relax, I think you'll be fine!",
  ui_story_5058_50580201_33_dialog_content = "In that case, I think PlayerName should tackle the hardest challenge!",
  ui_story_5058_50580201_34_dialog_content = "After you jump, inflatable Eclipsite dolls will be released around you.",
  ui_story_5058_50580201_35_dialog_content = "Snatch them on the way down to win commemorative stickers.",
  ui_story_5058_50580201_36_dialog_content = "And, you can take the inflatable Eclipsites home too!",
  ui_story_5058_50580201_37_dialog_content = "Who would want inflatable dolls that look like Eclipsites?!",
  ui_story_5058_50580201_38_dialog_content = "Me, me, I would!",
  ui_story_5058_50580201_39_dialog_content = "Please bring one back for me!",
  ui_story_5058_50580201_40_dialog_content = "What?",
  ui_story_5058_50580201_41_dialog_content = "Arghhhh—!",
  ui_story_5058_50580201_42_dialog_content = "You could've at least given me a warning!",
  ui_story_5058_50580202_1_dialog_content = "Are you okay? You keep rubbing your eyes... are you crying?",
  ui_story_5058_50580202_2_dialog_content = "No, that's not it!",
  ui_story_5058_50580202_3_dialog_content = "There were all these lights flashing in my eyes during the fall...",
  ui_story_5058_50580202_4_dialog_content = "Oh, that was a camera taking pictures. Wanna check out the pics?",
  ui_story_5058_50580202_5_dialog_content = "Forget it, I probably look awkward...",
  ui_story_5058_50580202_6_dialog_content = "Check out all the stickers I got!",
  ui_story_5058_50580202_7_dialog_content = "Huh? You both got them? Congrats on getting through the game!",
  ui_story_5058_50580202_8_dialog_content = "Every attraction in the park has challenges, and you get stickers for completing them.",
  ui_story_5058_50580202_9_dialog_content = "The more stickers you get, the better the prizes you can redeem.",
  ui_story_5058_50580202_10_dialog_content = "Hey, Carleen, wanna see who gets the better prize?",
  ui_story_5058_50580202_11_dialog_content = "Sure, but don't you get PlayerName to help you.",
  ui_story_5058_50580202_12_dialog_content = "It would be a miracle if I didn't have to help PlayerName, let alone the other way around.",
  ui_story_5058_50580202_13_dialog_content = "Hey, I can hear you, you know.",
  ui_story_5058_50580202_14_dialog_content = "Say, the butterfly on this sticker sure is gorgeous!",
  ui_story_5058_50580202_15_dialog_content = "That's no ordinary butterfly, but the Denuo Goddess unique to Denuo Valley.",
  ui_story_5058_50580202_16_dialog_content = "Does the Denuo Goddess really exist?",
  ui_story_5058_50580202_17_dialog_content = "I believe so! Someone just said they came across it in the resort recently...",
  ui_story_5058_50580202_18_dialog_content = "And a lot of tourists spent good money on our soft opening just for a chance to see it before anyone else.",
  ui_story_5058_50580202_19_dialog_content = "Thanks to PlayerName, we didn't have to spend any! But I wonder if we'll catch a glimpse of it this time...",
  ui_story_5058_50580202_20_dialog_content = "If it's real, why not just show it off to the public?",
  ui_story_5058_50580202_21_dialog_content = "All that hype only to leave it to a chance encounter... That sounds like a scam to me.",
  ui_story_5058_50580202_22_dialog_content = "Oh my, you must be the Caelestite that Cena mentioned. I could spot you from a mile away in the crowd!",
  ui_story_5058_50580202_23_dialog_content = "Why are you rubbing your eyes? They hurt or something?",
  ui_story_5058_50580202_24_dialog_content = "Well, uh...",
  ui_story_5058_50580202_25_dialog_content = "Looks like it's your first time trying bungee jumping.",
  ui_story_5058_50580202_26_dialog_content = "The first time can be a bit uncomfortable. Are those folks next to you your family or friends? Why do they seem so indifferent?",
  ui_story_5058_50580202_27_dialog_content = "Poor thing. Well, since they're not concerned about you... let us give you a soothing massage and help you relax.",
  ui_story_5058_50580202_28_dialog_content = "T-That's quite all right, thanks...",
  ui_story_5058_50580202_29_dialog_content = "Just relax! Our massage skills are top-notch.",
  ui_story_5058_50580202_30_dialog_content = "V-Vice, Carleen... Can either of you...",
  ui_story_5058_50580202_31_dialog_content = "I was wondering where the ladies went. You can't just hog them for yourself, PlayerName!",
  ui_story_5058_50580202_32_dialog_content = "What's up, cutie pie? Are you jealous?",
  ui_story_5058_50580202_33_dialog_content = "Sigh, never thought there'd be a day I'd end up second best.",
  ui_story_5058_50580202_34_dialog_content = "Come on, when did you start actin' all possessive? Here, let me give you a massage as well, alright?",
  ui_story_5058_50580202_35_dialog_content = "I knew I was Lina's favorite...",
  ui_story_5058_50580202_36_dialog_content = "S-Save me, Cena...",
  ui_story_5058_50580202_37_dialog_content = "What's that, PlayerName? You're going to make the ladies feel bad.",
  ui_story_5058_50580202_38_dialog_content = "What are you talking about? I don't even know who they are!",
  ui_story_5058_50580202_39_dialog_content = "You just want to know their names. Hahaha, I should accommodate you.",
  ui_story_5058_50580202_40_dialog_content = "I met all three ladies on previous journeys. They all love to travel.",
  ui_story_5058_50580202_41_dialog_content = "Don't let their manners fool you. They're very picky when it comes to trips.",
  ui_story_5058_50580202_42_dialog_content = "That's why I specifically invited them to the resort as consultants.",
  ui_story_5058_50580202_43_dialog_content = "The lady in the turban is Winona. We spent lots of time together in Northland searching through ancient ruins. We're tight as tight can be.",
  ui_story_5058_50580202_44_dialog_content = "Winona serves as our security consultant.",
  ui_story_5058_50580202_45_dialog_content = "Nice to meet you.",
  ui_story_5058_50580202_46_dialog_content = "The masseuse with the wonderful hands is Lastelle. I escorted her before when I worked as secret security in Lumopolis.",
  ui_story_5058_50580202_47_dialog_content = "Lastelle is a hospitality consultant specializing in relaxation. On top of that—",
  ui_story_5058_50580202_48_dialog_content = "Alright, that's enough. Don't spill all the beans, my dear. It'll just take away the element of surprise.",
  ui_story_5058_50580202_49_dialog_content = "When I was a cleaner in rural Umbraton, I saved Lina from thirty assassins. She's our gourmet consultant.",
  ui_story_5058_50580202_50_dialog_content = "I have no idea why so many people would try to kill Lina. She's clearly the kindest, most gentle woman I've met.",
  ui_story_5058_50580202_51_dialog_content = "Hee-hee... Cena, you never cease to impress with your smooth words, do you?",
  ui_story_5058_50580202_52_dialog_content = "Don't just stand there! Now that you're here, let's get to the fun part!",
  ui_story_5058_50580202_53_dialog_content = "You're right. After all that talking, we should check out the attractions!",
  ui_story_5058_50580202_54_dialog_content = "Why don't we go for something more low-key... Like the Ferris wheel over there?",
  ui_story_5058_50580202_55_dialog_content = "But... I have the Ferris wheel last on the itinerary.",
  ui_story_5058_50580202_56_dialog_content = "The view from it is even better at night because of the evening fireworks!",
  ui_story_5058_50580202_57_dialog_content = "Fireworks from atop the Ferris wheel? How romantic!",
  ui_story_5058_50580202_58_dialog_content = "Fireworks, huh...",
  ui_story_5058_50580202_59_dialog_content = "What's wrong, Cena? You don't like fireworks shows?",
  ui_story_5058_50580202_60_dialog_content = "No... I, uh, just...",
  ui_story_5058_50580202_61_dialog_content = "Just thought of a very special place in mind that I'd like to take the ladies to.",
  ui_story_5058_50580202_62_dialog_content = "I hope you won't let me down then.",
  ui_story_5058_50580202_63_dialog_content = "Of course not. Follow me, my lovely ladies!",
  ui_story_5058_50580202_64_dialog_content = "H-He's leaving, just like that?",
  ui_story_5058_50580202_65_dialog_content = "It's okay. Cena might say inappropriate things, but he's still a dependable person!",
  ui_story_5058_50580202_66_dialog_content = "He helped Lorelei restore the ecology in Denuo Valley for the resort to launch.",
  ui_story_5058_50580202_67_dialog_content = "Restore the ecology?",
  ui_story_5058_50580202_68_dialog_content = "Not that long ago, Denuo Valley was still barren.",
  ui_story_5058_50580202_69_dialog_content = "But Lorelei locked in on the land, invested a huge sum to improve the environment and restored it to what it used to be.",
  ui_story_5058_50580202_70_dialog_content = "That sounds like a lot of work.",
  ui_story_5058_50580202_71_dialog_content = "And Cena could always find a solution to complete any of Lorelei's seemingly crazy demands.",
  ui_story_5058_50580202_72_dialog_content = "Even Sinsa liked him enough to try to recruit him...",
  ui_story_5058_50580202_73_dialog_content = "Doesn't Sinsa say that to anybody he meets?",
  ui_story_5058_50580202_74_dialog_content = "But even then... Okay, maybe I should never judge a book by its cover.",
  ui_story_5058_50580202_75_dialog_content = "<color=#e8d9bb>Splashing—</color>",
  ui_story_5058_50580202_76_dialog_content = "So, is this the special place you were talking about?",
  ui_story_5058_50580202_77_dialog_content = "Yes. Don't you ladies prefer to swim and sunbathe somewhere quiet?",
  ui_story_5058_50580202_78_dialog_content = "Most of the guests are in the amusement park, so hardly anyone is here in the Oasis Pool. Feel free to enjoy yourselves.",
  ui_story_5058_50580202_79_dialog_content = "Cena, why don't you join us for a swim as well?",
  ui_story_5058_50580202_80_dialog_content = "Thank you, but I'm afraid I have to leave for the moment.",
  ui_story_5058_50580202_81_dialog_content = "Miss Lorelei's meeting is almost over. I gotta go find out what came out of it.",
  ui_story_5058_50580202_82_dialog_content = "Oh my. Cena, when did you start liking younger girls?",
  ui_story_5058_50580202_83_dialog_content = "I'd understand it coming from someone else, but don't tell me you still don't know my taste?",
  ui_story_5058_50580202_84_dialog_content = "I'm just a worker who wants to keep the boss happy so I can make the big bucks to indulge you!",
  ui_story_5058_50580202_85_dialog_content = "Really?",
  ui_story_5058_50580202_86_dialog_content = "Cena, there's obviously something on your mind that you don't wanna share with us.",
  ui_story_5058_50580202_87_dialog_content = "Well, whenever you feel like it, you can always come to us and talk, okay?",
  ui_story_5058_50580202_88_dialog_content = "Sure. Enjoy and have fun, ladies. Of course, don't skimp on the critiques and suggestions!",
  ui_story_5058_50580301_1_dialog_content = "Hey, this is rare, I haven't seen you this unhappy for a long time.",
  ui_story_5058_50580301_2_dialog_content = "What did the investors say in the board meeting?",
  ui_story_5058_50580301_3_dialog_content = "Have you heard of the <color=#FFB400>Denuo Incense</color>?",
  ui_story_5058_50580301_4_dialog_content = "Denuo Incense...",
  ui_story_5058_50580301_5_dialog_content = "Hmm, can't say I have before.",
  ui_story_5058_50580301_6_dialog_content = "So even you don't know about it either? The Board said it's a specialty spice in Denuo and a big fad once.",
  ui_story_5058_50580301_7_dialog_content = "They want us to produce and push it to the moon as the star product of the resort so we'll get repeat business.",
  ui_story_5058_50580301_8_dialog_content = "Wow, that's going to be tough... What did you tell them?",
  ui_story_5058_50580301_9_dialog_content = "That I'll take it under advisement. You know yourself how they've been pushing me to expand the resort and develop more of the valley in phase two.",
  ui_story_5058_50580301_10_dialog_content = "But they promised me that if we manufacture the Denuo Incense, they'll stop interfering with future developments.",
  ui_story_5058_50580301_11_dialog_content = "That sounds very tempting, considering the restrictions and conditions they demanded when we started the project.",
  ui_story_5058_50580301_12_dialog_content = "However, they also didn't offer any help on how to go about making the incense.",
  ui_story_5058_50580301_13_dialog_content = "Speaking of that, Denuo Village did trade with the outside world for a while. Maybe someone there made it.",
  ui_story_5058_50580301_14_dialog_content = "But the village is long gone now. How are we going to find the formula?",
  ui_story_5058_50580301_15_dialog_content = "That's true...",
  ui_story_5058_50580301_16_dialog_content = "Don't worry though, I dabble in spices too. Maybe I can give it a try.",
  ui_story_5058_50580301_17_dialog_content = "You even know about spices? What's the resort going to do without you!",
  ui_story_5058_50580301_18_dialog_content = "Haha, hopefully I can pull a rabbit out of the hat.",
  ui_story_5058_50580301_19_dialog_content = "Please! Even if it's not totally perfect, it will still benefit the valley.",
  ui_story_5058_50580301_20_dialog_content = "We can't abandon our original marketing plan, however. The Caelestite is still the focus.",
  ui_story_5058_50580301_21_dialog_content = "What, you didn't win any Denuo Goddess stickers on the White Night Dragons?",
  ui_story_5058_50580301_22_dialog_content = "...",
  ui_story_5058_50580301_23_dialog_content = "Carleen looks rather pale... Are roller coasters too much for you?",
  ui_story_5058_50580301_24_dialog_content = "How is it possible that someone could handle bungee jump but not a roller coaster?",
  ui_story_5058_50580301_25_dialog_content = "Maybe there's an issue with the itinerary. I should've separated the categories...",
  ui_story_5058_50580301_26_dialog_content = "But the Fantasy Matrix coming up next should offer a totally different thrill!",
  ui_story_5058_50580301_27_dialog_content = "Fantasy Matrix? Finally, that sounds like a simple, easy ride. Where is it?",
  ui_story_5058_50580301_28_dialog_content = "Ta-da! Right in front of us. Look up, PlayerName!",
  ui_story_5058_50580301_29_dialog_content = "Look up...?",
  ui_story_5058_50580301_30_dialog_content = "Holy... Talk about a giant buzzsaw! That's a ride? You sure?",
  ui_story_5058_50580301_31_dialog_content = "Yeah, Sinsa designed this, and like he used to say...",
  ui_story_5058_50580301_32_dialog_content = "All right, you punks, it's the buzzsaw for you if you're not fast enough to dodge!",
  ui_story_5058_50580301_33_dialog_content = "Eve? No, that doesn't go for you, Eve...!",
  ui_story_5058_50580301_34_dialog_content = "Yeah, that's something he would say.",
  ui_story_5058_50580301_35_dialog_content = "This is child's play. I see it's more stickers for me.",
  ui_story_5058_50580301_36_dialog_content = "That's the Carleen I know. Okay, let's get going, I can't wait!",
  ui_story_5058_50580301_37_dialog_content = "So, before we begin, don't forget the safety measures!",
  ui_story_5058_50580301_38_dialog_content = "<color=#e8d9bb>Buzzing—</color>",
  ui_story_5058_50580301_39_dialog_content = "Hurry up, Carleen, or I'll gonna beat you to it!",
  ui_story_5058_50580301_40_dialog_content = "I've been ready. You just watch out!",
  ui_story_5058_50580301_41_dialog_content = "Hey, wait for me... Why am I left behind again?",
  ui_story_5058_50580301_42_dialog_content = "Hey, you guys—",
  ui_story_5058_50580301_43_dialog_content = "They all ran off... Guess I'll just go wander on my own.",
  ui_story_5058_50580301_44_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5058_50580301_45_dialog_content = "Give it up to the best shooter of the match: Miss Smokey!",
  ui_story_5058_50580301_46_dialog_content = "Congratulations, you just won another Denuo Goddess sticker, 'ol great Director Smokey!",
  ui_story_5058_50580301_47_dialog_content = "You let me have the two last shots, didn't you, <color=#FFB400>Shashona</color>?",
  ui_story_5058_50580301_48_dialog_content = "What? No way! You're a young sharpshooter, Director Smokey. I just fudged a little.",
  ui_story_5058_50580301_49_dialog_content = "Just like you can probably fudge a little on the Board of Directors too.",
  ui_story_5058_50580301_50_dialog_content = "Ah, I see what's this about.",
  ui_story_5058_50580301_51_dialog_content = "Well, the Board is putting pressure on Lorelei to expand the project.",
  ui_story_5058_50580301_52_dialog_content = "But as every businessperson knows, haste makes waste.",
  ui_story_5058_50580301_53_dialog_content = "Why can't we just build up the resort brand, then reinvest the money back into more projects?",
  ui_story_5058_50580301_54_dialog_content = "I'm hardly interested in running a business or listening to their suggestions.",
  ui_story_5058_50580301_55_dialog_content = "As long as the rides are exciting and fun enough for me, I don't care about the rest.",
  ui_story_5058_50580301_56_dialog_content = "Speaking of that, all of the attractions aren't challenging enough. Make sure you let Lorelei know...",
  ui_story_5058_50580301_57_dialog_content = "Make everything harder and add more scoring gimmicks. Not all have to be shooting at big Eclipsites like Halo Shots. That's boring.",
  ui_story_5058_50580301_58_dialog_content = "You think so? I thought it was fun playing it with you. Another round?",
  ui_story_5058_50580301_59_dialog_content = "Target in sight—",
  ui_story_5058_50580301_60_dialog_content = "What target? Me?",
  ui_story_5058_50580301_61_dialog_content = "What are you doing here?",
  ui_story_5058_50580301_62_dialog_content = "I got an invitation from Lorelei for the soft opening. You got one too?",
  ui_story_5058_50580301_63_dialog_content = "Unlike you, I'm a director for the resort, here to review the progress.",
  ui_story_5058_50580301_64_dialog_content = "You're... a member of the Board of Directors?",
  ui_story_5058_50580301_65_dialog_content = "Why is that a surprise? Sure, I've never done it, but I thought it would be interesting to invest in a resort.",
  ui_story_5058_50580301_66_dialog_content = "And I scored in a casino lately with money burning a hole in my pocket, so I might as well spend it.",
  ui_story_5058_50580301_67_dialog_content = "Sounds really good to be rich...",
  ui_story_5058_50580301_68_dialog_content = "Are you... the Caelestite? I'm impressed that Lorelei managed to get you here.",
  ui_story_5058_50580301_69_dialog_content = "Uh, you're too kind. Just call me PlayerName.",
  ui_story_5058_50580301_70_dialog_content = "Cool! Glad to meet you, PlayerName, I'm Shashona.",
  ui_story_5058_50580301_71_dialog_content = "Please enjoy yourself! Let's talk again after you've gone through all the rides.",
  ui_story_5058_50580301_72_dialog_content = "The Board should be very interested in PlayerName's comments, right?",
  ui_story_5058_50580301_73_dialog_content = "Say, have you tried Fantasy Matrix yet? That seems to be fun.",
  ui_story_5058_50580301_74_dialog_content = "Why does everyone want that? I'd prefer to try something else.",
  ui_story_5058_50580301_75_dialog_content = "Well then, try this out. It's not difficult and should be easy for you.",
  ui_story_5058_50580301_76_dialog_content = "Just point the gun at the Eclipsites and fire away.",
  ui_story_5058_50580301_77_dialog_content = "<color=#e8d9bb>Bang, bang!</color>",
  ui_story_5058_50580301_78_dialog_content = "Whoa, it's starting already? By the way, the Eclipsites are as real as it gets!",
  ui_story_5058_50580301_79_dialog_content = "This is a contest. If you win, you can ride the Fantasy Matrix with me!",
  ui_story_5058_50580301_80_dialog_content = "No, that's okay, all I want are stickers...",
  ui_story_5058_50580402_1_dialog_content = "Hey, you've impressed me since the last time I saw you! Though you're not in my league.",
  ui_story_5058_50580402_2_dialog_content = "Uh, I'm sure very few people could outshoot you.",
  ui_story_5058_50580402_3_dialog_content = "I played with almost everything and got all the stickers... What's left to do?",
  ui_story_5058_50580402_4_dialog_content = "There are many hotel amenities worth experiencing. How about getting an oil massage?",
  ui_story_5058_50580402_5_dialog_content = "I sent Lorelei to beg the master in the most renowned locale to custom-make the essence for the resort. You can't get that anywhere else.",
  ui_story_5058_50580402_6_dialog_content = "Sure, I'll check it out. See you later.",
  ui_story_5058_50580402_7_dialog_content = "Would you be interested as well, old friend of Smokey's?",
  ui_story_5058_50580402_8_dialog_content = "Well, we're friends, but probably not close enough to get a massage together...",
  ui_story_5058_50580402_9_dialog_content = "Heheh, nothing to it. Friends often go hot-tubbing, let alone massage.",
  ui_story_5058_50580402_10_dialog_content = "Maybe you can even discuss potential collaborations...",
  ui_story_5058_50580402_11_dialog_content = "Wow, you still got business in mind in your downtown... Much more of a director than Smokey.",
  ui_story_5058_50580402_12_dialog_content = "Thanks for the compliment, but I'm not a director, just a relative of Lorelei's, to lend a helping hand.",
  ui_story_5058_50580402_13_dialog_content = "Lorelei's relative, I see...",
  ui_story_5058_50580402_14_dialog_content = "PlayerName!",
  ui_story_5058_50580402_15_dialog_content = "Here you are! Nobody could find you and we were worried...",
  ui_story_5058_50580402_16_dialog_content = "Oh, sorry. When you were getting on Fantasy Matrix, I—",
  ui_story_5058_50580402_17_dialog_content = "... What are you doing here?",
  ui_story_5058_50580402_18_dialog_content = "Oh, Laurie, how come you didn't tell me the resort is open?",
  ui_story_5058_50580402_19_dialog_content = "The guest count seems low for an operation of this scale.",
  ui_story_5058_50580402_20_dialog_content = "It's just a soft opening before the real grand opening. Everyone here is invitation-only.",
  ui_story_5058_50580402_21_dialog_content = "Ah, then I guessed right that this fellow is here to promote the park?",
  ui_story_5058_50580402_22_dialog_content = "You get a pass for making the Caelestite the park spokesperson.",
  ui_story_5058_50580402_23_dialog_content = "But if you had told me sooner, I would have come earlier and personally shown PlayerName around so there's no lonely person...",
  ui_story_5058_50580402_24_dialog_content = "I knew you would do that, that's why—",
  ui_story_5058_50580402_25_dialog_content = "Look at your complexion, you must not be properly hydrated.",
  ui_story_5058_50580402_26_dialog_content = "I brought some supplements from home. I'll cook them for you tonight.",
  ui_story_5058_50580402_27_dialog_content = "Mom, please don't go into that in front of a guest. I'm old enough to handle myself.",
  ui_story_5058_50580402_28_dialog_content = "(W-What? Shashona is Lorelei's mom?!)",
  ui_story_5058_50580402_29_dialog_content = "Anyway, I have to leave and take our guest here to check-in.",
  ui_story_5058_50580402_30_dialog_content = "This way, please, PlayerName.",
  ui_story_5058_50580402_31_dialog_content = "Slow down, Laurie. Why aren't you wearing the shoes I bought you? That pair is not for work...",
  ui_story_5058_50580402_32_dialog_content = "Whew...",
  ui_story_5058_50580402_33_dialog_content = "Your mom is very good to you, Lorelei.",
  ui_story_5058_50580402_34_dialog_content = "She certainly is.",
  ui_story_5058_50580501_1_dialog_content = "Okay, you're all checked in.",
  ui_story_5058_50580501_2_dialog_content = "Thanks, Lorelei.",
  ui_story_5058_50580501_3_dialog_content = "Part of my job, and truth be told, I should do more since you're our premier VIP.",
  ui_story_5058_50580501_4_dialog_content = "Hmm, have I explained the facility features of the hotel to you yet?",
  ui_story_5058_50580501_5_dialog_content = "Ahem, in addition to comfy, cozy guest rooms, the hotel also has a gym, a swimming pool, hot springs, spa...",
  ui_story_5058_50580501_6_dialog_content = "There are marks at the stairs of every level, so no worries about getting lost.",
  ui_story_5058_50580501_7_dialog_content = "The interior also features the latest ventilation system, so during inclement weather like a sandstorm, we'll run it to provide fresh air.",
  ui_story_5058_50580501_8_dialog_content = "You're not going to encounter any discomfort during any long-term stay.",
  ui_story_5058_50580501_9_dialog_content = "Also, breakfast and lunch are buffet-style, just go to the restaurant and you'll be fine...",
  ui_story_5058_50580501_10_dialog_content = "PlayerName!",
  ui_story_5058_50580501_11_dialog_content = "Where have you been? We couldn't find you after we got off the ride.",
  ui_story_5058_50580501_12_dialog_content = "Sorry about that... I was trying out Halo Shots and met a lady named Shashona.",
  ui_story_5058_50580501_13_dialog_content = "So Shashona's here.",
  ui_story_5058_50580501_14_dialog_content = "Do you know her?",
  ui_story_5058_50580501_15_dialog_content = "How do I put this... She's not someone we should trifle with.",
  ui_story_5058_50580501_16_dialog_content = "Why? Is she a bigwig?",
  ui_story_5058_50580501_17_dialog_content = "Shashona is actually Lorelei's mom.",
  ui_story_5058_50580501_18_dialog_content = "Lorelei's mom is here too? How can we lionize Lorelei's time in that case?",
  ui_story_5058_50580501_19_dialog_content = "Well, we should be thankful to have Bopper with us.",
  ui_story_5058_50580501_20_dialog_content = "Ahem... Thanks, everyone. Please know it's my mission to provide quality service to our guests. As for my mom... She comes to see me quite often, actually.",
  ui_story_5058_50580501_21_dialog_content = "Oh, and I'm wondering how do you feel about the attractions?",
  ui_story_5058_50580501_22_dialog_content = "Honestly, a lot of those were just too much for me.",
  ui_story_5058_50580501_23_dialog_content = "I think they're perfectly exciting. I had lotsa fun.",
  ui_story_5058_50580501_24_dialog_content = "I can tell... But I get tired just looking at them and would love a break right now.",
  ui_story_5058_50580501_25_dialog_content = "Ah, ah, I see.",
  ui_story_5058_50580501_26_dialog_content = "The Board of Directors always wanted more thrill rides. I see we need more attractions for people of all ages instead.",
  ui_story_5058_50580501_27_dialog_content = "(People of all ages? We're about the same age...!)",
  ui_story_5058_50580501_28_dialog_content = "Thank you for the valuable feedback, PlayerName!",
  ui_story_5058_50580501_29_dialog_content = "Is everyone else calling it quits for now, or should we continue checking out the rides?",
  ui_story_5058_50580501_30_dialog_content = "We ran through quite a lot and I'm feeling a little exhausted.",
  ui_story_5058_50580501_31_dialog_content = "Yeah, I agree... But we haven't collected all the Denuo Goddess stickers yet!",
  ui_story_5058_50580501_32_dialog_content = "It's all right, you still have several more days to do that.",
  ui_story_5058_50580501_33_dialog_content = "Cool, I want to collect all the pretty Denuo Goddess stickers!",
  ui_story_5058_50580501_34_dialog_content = "Speaking of that, do you guys wanna take a tour of the valley?",
  ui_story_5058_50580501_35_dialog_content = "It has a lot of butterflies, and maybe we'll see the real Denuo Goddess!",
  ui_story_5058_50580501_36_dialog_content = "When you rest up, I can take you to check out the valley.",
  ui_story_5058_50580501_37_dialog_content = "The area is still undeveloped but could become part of the resort in the future.",
  ui_story_5058_50580501_38_dialog_content = "Wonderful! This trip would be extra worth it if we saw the Denuo Goddess!",
  ui_story_5058_50580501_39_dialog_content = "Why don't we go now?",
  ui_story_5058_50580501_40_dialog_content = "I agree.",
  ui_story_5058_50580501_41_dialog_content = "Didn't you want to rest for a while?",
  ui_story_5058_50580501_42_dialog_content = "We heard Miss Lorelei spent a lot of effort to turn Denuo Valley green.",
  ui_story_5058_50580501_43_dialog_content = "I get excited just thinking about the green, lush landscape!",
  ui_story_5058_50580501_44_dialog_content = "Me too.",
  ui_story_5058_50580501_45_dialog_content = "I see. Why not, let's take off now!",
  ui_story_5058_50580501_46_dialog_content = "<color=#e8d9bb>After a while...</color>",
  ui_story_5058_50580501_47_dialog_content = "Breathe...",
  ui_story_5058_50580501_48_dialog_content = "The air is so clean. I took a deep inhale, and even my mouth was refreshed.",
  ui_story_5058_50580501_49_dialog_content = "The pleasant scent of the grass reminds me of Eraveil.",
  ui_story_5058_50580501_50_dialog_content = "Yes, the plants seem naturally grown without any sign of artificiality.",
  ui_story_5058_50580501_51_dialog_content = "That's what nature is supposed to be. Just plant the seeds, nourish them and they will surprise us.",
  ui_story_5058_50580501_52_dialog_content = "This is impressive, Lorelei, building a resort like this in Rediesel Desert. But what gave you the idea?",
  ui_story_5058_50580501_53_dialog_content = "The Denuo Valley itself has geographical barriers to cordon off Eclipsite incursions.",
  ui_story_5058_50580501_54_dialog_content = "And the natural landscape here is completely different from other tourist spots in Astra.",
  ui_story_5058_50580501_55_dialog_content = "Thus, a resort would provide a completely different experience for visitors.",
  ui_story_5058_50580501_56_dialog_content = "This is also a very important place to me. It's my wish to revive the surroundings...",
  ui_story_5058_50580501_57_dialog_content = "...",
  ui_story_5058_50580501_58_dialog_content = "I understand how you feel. It's exactly how I feel about Eraveil.",
  ui_story_5058_50580501_59_dialog_content = "(Does that mean this is where Lorelei was from?)",
  ui_story_5058_50580501_60_dialog_content = "Nice speech, but Miss Lorelei is a businessperson at heart, so it's all about profits.",
  ui_story_5058_50580501_61_dialog_content = "Of course. I'm extremely confident in the project!",
  ui_story_5058_50580501_62_dialog_content = "Hey, I see butterflies.",
  ui_story_5058_50580501_63_dialog_content = "Yes! I see several over there too!",
  ui_story_5058_50580501_64_dialog_content = "I wonder if the Denuo Goddess is among them.",
  ui_story_5058_50580501_65_dialog_content = "Miss Lorelei, c-can I go look for the Denuo Goddess?",
  ui_story_5058_50580501_66_dialog_content = "You even got a net ready to go, Bopper?!",
  ui_story_5058_50580501_67_dialog_content = "A lot of people asked me if it's true that the Denuo Goddess is in the valley... I'd love to prove it to them!",
  ui_story_5058_50580501_68_dialog_content = "All right, but if you run across them, be careful not to harm them.",
  ui_story_5058_50580501_69_dialog_content = "Why don't we look too? There's strength in numbers!",
  ui_story_5058_50580501_70_dialog_content = "We can even split up to cover more ground!",
  ui_story_5058_50580501_71_dialog_content = "You're turning it into another competition, aren't you?",
  ui_story_5058_50580501_72_dialog_content = "Heehee, don't look at me that way... Why don't I team up with Carleen this time then?",
  ui_story_5058_50580501_73_dialog_content = "Come on, let's go! Let's see who finds the Goddess first!",
  ui_story_5058_50580501_74_dialog_content = "Yawn—",
  ui_story_5058_50580501_75_dialog_content = "Kids... A nice day like this is perfect for a nap.",
  ui_story_5058_50580501_76_dialog_content = "Zzzz—Zzzz—",
  ui_story_5058_50580501_77_dialog_content = "Come here, Carleen, I found it!",
  ui_story_5058_50580501_78_dialog_content = "So quickly?",
  ui_story_5058_50580501_79_dialog_content = "Ta-da!",
  ui_story_5058_50580501_80_dialog_content = "Huh? What's that?",
  ui_story_5058_50580501_81_dialog_content = "I've never seen a moth this big before!",
  ui_story_5058_50580501_82_dialog_content = "Stay away from me!!!",
  ui_story_5058_50580501_83_dialog_content = "Have you seen the Denuo Goddess, little butterflies?",
  ui_story_5058_50580501_84_dialog_content = "You're fluttering clockwise around me... What are you trying to say?",
  ui_story_5058_50580501_85_dialog_content = "Hmm, I guess I can only read Lepidoz's mind...",
  ui_story_5058_50580501_86_dialog_content = "What are you doing, PlayerName?",
  ui_story_5058_50580501_87_dialog_content = "I-I'm just waiting for the right time...",
  ui_story_5058_50580501_88_dialog_content = "Don't move... There's a butterfly on your head.",
  ui_story_5058_50580501_89_dialog_content = "Cena, come take our pictures!",
  ui_story_5058_50580501_90_dialog_content = "Yawn—",
  ui_story_5058_50580501_91_dialog_content = "Coming...",
  ui_story_5058_50580501_92_dialog_content = "<color=#e8d9bb>Snap!</color>",
  ui_story_5058_50580501_93_dialog_content = "Well, all that effort and still no Denuo Goddess.",
  ui_story_5058_50580501_94_dialog_content = "I've had doubts about the existence of the Denuo Goddess myself, to be honest.",
  ui_story_5058_50580501_95_dialog_content = "I'm not sure either. Didn't you say you saw one before, Cena?",
  ui_story_5058_50580501_96_dialog_content = "I said that? Don't quite recall...",
  ui_story_5058_50580501_97_dialog_content = "Some alleged they saw the Denuo Goddess, but the Goddess is actually a myth more than anything else.",
  ui_story_5058_50580501_98_dialog_content = "Many investors invested in the resort simply because they heard it's in the valley.",
  ui_story_5058_50580501_99_dialog_content = "They wanted it to be a gimmick to draw tourists... I could not buck the Board's decision.",
  ui_story_5058_50580501_100_dialog_content = "But when I witnessed the overwhelming love and support from the patrons for the Denuo Goddess stickers and how they're even willing to pay big money just to see one here, it made me panic a bit.",
  ui_story_5058_50580501_101_dialog_content = "Because from construction to now, none of us have seen one here.",
  ui_story_5058_50580501_102_dialog_content = "If the Denuo Goddess is not real, it's false advertising and I don't want to lie to the guests...",
  ui_story_5058_50580501_103_dialog_content = "But if it's real, wouldn't what I'm doing attract those who might harm the Goddess...",
  ui_story_5058_50580501_104_dialog_content = "I didn't mean to cover it up. I just couldn't figure out a solution to this complicated issue... I'm sorry!",
  ui_story_5058_50580501_105_dialog_content = "We should be the ones apologizing for how reckless and rude we were.",
  ui_story_5058_50580501_106_dialog_content = "It's all right. If the Goddess could be found, maybe we can proliferate them.",
  ui_story_5058_50580501_107_dialog_content = "Plus, I know you'd never harm the butterflies. And I had fun myself too.",
  ui_story_5058_50580501_108_dialog_content = "It's the other people I'm skittish about...",
  ui_story_5058_50580501_109_dialog_content = "I can tell you don't give up easily, Lorelei. We can figure it out together.",
  ui_story_5058_50580501_110_dialog_content = "Yes! I've tracked down an animal expert who might be able to provide helpful suggestions.",
  ui_story_5058_50580501_111_dialog_content = "(Animal expert? Couldn't be Vic, could it?)",
  ui_story_5058_50580501_112_dialog_content = "I still hope such beautiful butterflies are real.",
  ui_story_5058_50580501_113_dialog_content = "The butterflies on the stickers are supposedly young ones.",
  ui_story_5058_50580501_114_dialog_content = "Rumor has it that adult Goddesses are huge, slender, and white throughout.",
  ui_story_5058_50580501_115_dialog_content = "How huge is huge? The size of the lizard, maybe?",
  ui_story_5058_50580501_116_dialog_content = "Guys, check out that bush over there... Is that the Denuo Goddess?",
  ui_story_5058_50580501_117_dialog_content = "Where?",
  ui_story_5058_50580501_118_dialog_content = "There, completely white...",
  ui_story_5058_50580501_119_dialog_content = "Roar!!!",
  ui_story_5058_50580501_120_dialog_content = "Eclipsites?",
  ui_story_5058_50580501_121_dialog_content = "How can there be Eclipsites in Denuo Valley?",
  ui_story_5058_50580502_1_dialog_content = "Oh no, I got separated...",
  ui_story_5058_50580502_2_dialog_content = "Hiss—",
  ui_story_5058_50580502_3_dialog_content = "What's that noise?",
  ui_story_5058_50580502_4_dialog_content = "Hiss—!",
  ui_story_5058_50580502_5_dialog_content = "PlayerName... PlayerName?",
  ui_story_5058_50580502_6_dialog_content = "Someone's... calling my name?",
  ui_story_5058_50580502_7_dialog_content = "Found you! Little troublemaker! Time to come home with Mommy for dinner. You know people gotta eat to grow, right?",
  ui_story_5058_50580502_8_dialog_content = "M-Mom...",
  ui_story_5058_50580502_9_dialog_content = "The feeling... So comfortable, cozy, familiar...",
  ui_story_5058_50580502_10_dialog_content = "Come with Mommy. Let's go home.",
  ui_story_5058_50580502_11_dialog_content = "Sure...",
  ui_story_5058_50580502_12_dialog_content = "... not!",
  ui_story_5058_50580502_13_dialog_content = "I thought I was in the resort...? And we just ran into Eclipsites, even.",
  ui_story_5058_50580502_14_dialog_content = "Am I dreaming? Or having a vision?",
  ui_story_5058_50580502_15_dialog_content = "What's wrong, PlayerName? Why are you not coming?",
  ui_story_5058_50580502_16_dialog_content = "I really want to keep dreaming...",
  ui_story_5058_50580502_17_dialog_content = "But rats, how come I can't wake up?",
  ui_story_5058_50580502_18_dialog_content = "If this keeps up, I can only...",
  ui_story_5058_50580502_19_option_content = "Force Boost!",
  ui_story_5058_50580502_20_dialog_content = "Hiss—",
  ui_story_5058_50580502_21_dialog_content = "Am I awake now?",
  ui_story_5058_50580502_22_dialog_content = "...",
  ui_story_5058_50580502_23_dialog_content = "Who are you?",
  ui_story_5058_50580502_24_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5058_50580502_25_dialog_content = "The town... sandy and dusty... Is it an Eclipsite colony?",
  ui_story_5058_50580502_26_dialog_content = "Am I in someone else's dream?",
  ui_story_5058_50580502_27_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50580502_28_dialog_content = "The sandstorm is... getting worse...",
  ui_story_5058_50580502_29_dialog_content = "I'm...",
  ui_story_5058_50580502_30_dialog_content = "... suffocating...",
  ui_story_5058_50580601_1_dialog_content = "PlayerName!",
  ui_story_5058_50580601_2_dialog_content = "Mom...?",
  ui_story_5058_50580601_3_dialog_content = "Wake up, PlayerName!",
  ui_story_5058_50580601_4_dialog_content = "Vice... Carleen... Guys?",
  ui_story_5058_50580601_5_dialog_content = "Good, you're awake! Sorry for leaving you behind. We didn't notice until we were far away.",
  ui_story_5058_50580601_6_dialog_content = "Sorry, I'm probably exhausted from all the activities today...",
  ui_story_5058_50580601_7_dialog_content = "I felt drowsy when I was running and couldn't help but fell asleep, even had strange dreams that I just couldn't wake up from.",
  ui_story_5058_50580601_8_dialog_content = "You freaked me out...",
  ui_story_5058_50580601_9_dialog_content = "Good to see PlayerName is all right. It would be a loss for Astra otherwise that couldn't be recouped even if I sold all my assets.",
  ui_story_5058_50580601_10_dialog_content = "But how come there are Eclipsites here?",
  ui_story_5058_50580601_11_dialog_content = "I'm not sure, either... The canyon is contentious enough for them to venture into, usually.",
  ui_story_5058_50580601_12_dialog_content = "I only hired a small security team to patrol the outer perimeters.",
  ui_story_5058_50580601_13_dialog_content = "I thought that would be enough to keep you safe... I'm very sorry!",
  ui_story_5058_50580601_14_dialog_content = "Cena, we have to acquire anti-Eclipsite weapons pronto when we get back.",
  ui_story_5058_50580601_15_dialog_content = "Got it. So what do we do now...?",
  ui_story_5058_50580601_16_dialog_content = "Let's return to the park. We need a plan for this.",
  ui_story_5058_50580601_17_dialog_content = "Graagh!",
  ui_story_5058_50580601_18_dialog_content = "Eek, It's so scary!",
  ui_story_5058_50580601_19_dialog_content = "<color=#e8d9bb>Bang!</color>",
  ui_story_5058_50580601_20_dialog_content = "One shot, one kill!",
  ui_story_5058_50580601_21_dialog_content = "That's more like it! The show is getting off to a very authentic and exciting start.",
  ui_story_5058_50580601_22_dialog_content = "Has the show started already?",
  ui_story_5058_50580601_23_dialog_content = "Haven't you heard a word I said, Master? I don't see any wondrous beast here... Just how legit is this assignment you got?",
  ui_story_5058_50580601_24_dialog_content = "Aw, never mind. I'm not gonna waste any more of my time. I'm going back to see the show!",
  ui_story_5058_50580601_25_dialog_content = "It's good to be young... Not like the old set of bones I got. It's better for me to snooze using little furball as a pillow.",
  ui_story_5058_50580601_26_dialog_content = "Gahhhh!",
  ui_story_5058_50580601_27_dialog_content = "Wow, the Eclipsites are really lifelike this time, even the molars look authentic...",
  ui_story_5058_50580601_28_dialog_content = "Roar!",
  ui_story_5058_50580601_29_dialog_content = "No, stupid Master, that's a real Eclipsite!",
  ui_story_5058_50580601_30_dialog_content = "The Eclipsites invaded the park, indeed...",
  ui_story_5058_50580601_31_dialog_content = "Cena, evacuate the guests. Bopper, escort everyone to the hotel. I gotta get security to dispose of the Eclipsites.",
  ui_story_5058_50580601_32_dialog_content = "No problem, boss, though the Board will probably be harder to deal with than the Eclipsites.",
  ui_story_5058_50580601_33_dialog_content = "...",
  ui_story_5058_50580601_34_dialog_content = "Who promised no Eclipsite would ever show up here?",
  ui_story_5058_50580601_35_dialog_content = "You owed us an explanation, Lorelei!",
  ui_story_5058_50580601_36_dialog_content = "Now is not the time to discuss that issue.",
  ui_story_5058_50580601_37_dialog_content = "You're here, Lady Carleen?",
  ui_story_5058_50580601_38_dialog_content = "I'm just assisting my father with his investment on my off days, nothing more!",
  ui_story_5058_50580601_39_dialog_content = "Needless clarification.",
  ui_story_5058_50580601_40_dialog_content = "The Eclipsites are truly my fault and negligence, Directors, but your safety is the paramount concern...",
  ui_story_5058_50580601_41_dialog_content = "Please follow the staff back to the hotel for shelter. I'll handle everything and explain it later!",
  ui_story_5058_50580601_42_dialog_content = "Bopper, I'll leave PlayerName and pals with you.",
  ui_story_5058_50580601_43_dialog_content = "Okay!",
  ui_story_5058_50580601_44_dialog_content = "But we can't and shouldn't leave you to face all this alone, Lorelei...",
  ui_story_5058_50580601_45_dialog_content = "Yes. It will go much faster for us to remove the Eclipsites together.",
  ui_story_5058_50580601_46_dialog_content = "That's right, we're all experienced, you know!",
  ui_story_5058_50580601_47_dialog_content = "This is unexpected. I didn't think you would...",
  ui_story_5058_50580601_48_dialog_content = "Hey, is that Vic and Fia? They're fighting too!",
  ui_story_5058_50580601_49_dialog_content = "Let's get rid of the Eclipsites around us, then join them!",
  ui_story_5058_50580601_50_dialog_content = "Yes!",
  ui_story_5058_50580601_51_dialog_content = "I see I am forced to fight alongside you peasants for the sake of Lady Carleen.",
  ui_story_5058_50580702_1_dialog_content = "All Eclipsites in the immediate vicinity have been dealt with. Thank you all for your help.",
  ui_story_5058_50580702_2_dialog_content = "But I must insist you take shelter in the hotel and let me handle the rest.",
  ui_story_5058_50580702_3_dialog_content = "You always say \"Let me handle the rest\", but nothing is ever as simple as that.",
  ui_story_5058_50580702_4_dialog_content = "Shashona...",
  ui_story_5058_50580702_5_dialog_content = "I didn't want you to come here and build a resort. Sure enough, something bad's happening!",
  ui_story_5058_50580702_6_dialog_content = "You saw the directors' faces too. They don't think you can pull it off at all.",
  ui_story_5058_50580702_7_dialog_content = "Do as I say as shut the park down now.",
  ui_story_5058_50580702_8_dialog_content = "Mom, how can you be so irresponsible now?",
  ui_story_5058_50580702_9_dialog_content = "I can't leave my staff and guests hanging, nor can I betray the investors.",
  ui_story_5058_50580702_10_dialog_content = "Do you know what I went through to build this resort?",
  ui_story_5058_50580702_11_dialog_content = "You want me to shut it down when it's finally about to launch?",
  ui_story_5058_50580702_12_dialog_content = "I know you made a lot of sacrifices, that's why I feel this is not worth it!",
  ui_story_5058_50580702_13_dialog_content = "The family would help you with anything you wanted to do, yet you insisted on going alone...",
  ui_story_5058_50580702_14_dialog_content = "Don't worry about me, Mom. Go back to the hotel and I'll handle everything.",
  ui_story_5058_50580702_15_dialog_content = "But no matter what, I'm not going to shut the park down.",
  ui_story_5058_50580702_16_dialog_content = "Listen to me, Laurie...",
  ui_story_5058_50580702_17_dialog_content = "Ms. Shashona!",
  ui_story_5058_50580702_18_dialog_content = "Cena is here. He can take you. I still got a lot of business to tend to.",
  ui_story_5058_50580702_19_dialog_content = "It's been a long time, Ms. Shashona.",
  ui_story_5058_50580702_20_dialog_content = "...",
  ui_story_5058_50580702_21_dialog_content = "This is a farce!",
  ui_story_5058_50580702_22_dialog_content = "The hotel is that way...",
  ui_story_5058_50580702_23_dialog_content = "Bopper, I'm concerned that some guests might still be in the park. I'll send security to check again.",
  ui_story_5058_50580702_24_dialog_content = "You and the hotel staff check with the guests to accommodate their needs.",
  ui_story_5058_50580702_25_dialog_content = "I'll see you after I check the hotel's emergency measures.",
  ui_story_5058_50580702_26_dialog_content = "Huh? But that's not in my job description...",
  ui_story_5058_50580702_27_dialog_content = "PlayerName, Vice, Carleen, you guys should return to your rooms. I'll meet back up with you after things calm down.",
  ui_story_5058_50580702_28_dialog_content = "You are short on people right now, Miss Lorelei. Let us help.",
  ui_story_5058_50580702_29_dialog_content = "I for one don't want to be treated like an ordinary tourist! We chased butterflies and fought Eclipsites together, and that makes us friends!",
  ui_story_5058_50580702_30_dialog_content = "Thank you, but I must do this on my own. You saw what went down...",
  ui_story_5058_50580702_31_dialog_content = "Because your mom objected? I actually get how much you want to do this on your own.",
  ui_story_5058_50580702_32_dialog_content = "Was I too hard on my mom?",
  ui_story_5058_50580702_33_dialog_content = "Is there something on your mind, Lorelei? We'll listen if you don't mind...",
  ui_story_5058_50580702_34_dialog_content = "Yes, don't keep it bottled inside of you.",
  ui_story_5058_50580702_35_dialog_content = "Well, I didn't want to act that way, but for some reason, I was never on good terms with my mom since I struck out on my own.",
  ui_story_5058_50580702_36_dialog_content = "I know she loves me very much. She tolerates and accepts everything I do except for starting my own business...",
  ui_story_5058_50580702_37_dialog_content = "And that's exactly why I have to prove I can handle things by myself.",
  ui_story_5058_50580702_38_dialog_content = "The more she tries to stop me, the more I fight back...",
  ui_story_5058_50580702_39_dialog_content = "That's probably childish, but I just can't control myself...",
  ui_story_5058_50580702_40_dialog_content = "It's hard for a person to introspect like you just did already. I understand your mom, though, she's afraid that you'll get hurt...",
  ui_story_5058_50580702_41_dialog_content = "Yes, she is not blaming you or anything. She's just worried about you.",
  ui_story_5058_50580702_42_dialog_content = "Everybody loses control sometimes, but a little mutual understanding will be enough.",
  ui_story_5058_50580702_43_dialog_content = "I hope that's the case too.",
  ui_story_5058_50580702_44_dialog_content = "But to prevent her from trying to stop me from doing anything in the future, I must hurdle this crisis on hand.",
  ui_story_5058_50580702_45_dialog_content = "Just apologize to her after it blows over.",
  ui_story_5058_50580702_46_dialog_content = "Right! I do feel a weight off my shoulders.",
  ui_story_5058_50580702_47_dialog_content = "Then let us be a part of your crisis-management plan!",
  ui_story_5058_50580702_48_dialog_content = "We'll ride it out together, and then she'll see you in a new light for sure!",
  ui_story_5058_50580702_49_dialog_content = "Don't forget your Rediesel Wrench workers, either.",
  ui_story_5058_50580702_50_dialog_content = "Thank you.",
  ui_story_5058_50580702_51_dialog_content = "So, what are your instructions, boss?",
  ui_story_5058_50580702_52_dialog_content = "First, we have to keep the guests calm and assure their safety.",
  ui_story_5058_50580702_53_dialog_content = "Once we've secured the hotel perimeters, find all the breaches and take appropriate measures to fix them.",
  ui_story_5058_50580702_54_dialog_content = "There's the job for your Rediesel Wrench staff, Bopper.",
  ui_story_5058_50580702_55_dialog_content = "It's fine as long as they get paid.",
  ui_story_5058_50580801_1_dialog_content = "Don't be in such a hurry, Ms. Shashona...",
  ui_story_5058_50580801_2_dialog_content = "Whoa, why don't we calm down and put that gun away?",
  ui_story_5058_50580801_3_dialog_content = "There's nothing to talk about with a charlatan like you.",
  ui_story_5058_50580801_4_dialog_content = "Why did you come back to Lorelei this time?",
  ui_story_5058_50580801_5_dialog_content = "You got it all wrong, it's just a coincidence...",
  ui_story_5058_50580801_6_dialog_content = "Coincidence? I'm guessing you found out Lorelei is a rich girl now and wanted to scam her?",
  ui_story_5058_50580801_7_dialog_content = "You were just a servant my husband and I hired from one of our trips.",
  ui_story_5058_50580801_8_dialog_content = "One day, you brought Lorelei to me and asked for an advance so you could take her to see a doctor.",
  ui_story_5058_50580801_9_dialog_content = "I couldn't stand to see her bawl so I decided to foster her.",
  ui_story_5058_50580801_10_dialog_content = "Whether you truly intended to help her, I already paid you a pretty good sum.",
  ui_story_5058_50580801_11_dialog_content = "And you also promised me you will never be around her again.",
  ui_story_5058_50580801_12_dialog_content = "Only for you to show back up more than ten years later, and then her raise a stink about launching a resort in Denuo Valley immediately. You call that a coincidence?",
  ui_story_5058_50580801_13_dialog_content = "Listen to me, Ms. Shashona, I really did meet Lorelei through sheer chance.",
  ui_story_5058_50580801_14_dialog_content = "And I decided to help because I admired her idea to make the valley green.",
  ui_story_5058_50580801_15_dialog_content = "You also know full well I work odd jobs and I need to make a living.",
  ui_story_5058_50580801_16_dialog_content = "Then what did you do other than get paid? This valley is completely unsafe.",
  ui_story_5058_50580801_17_dialog_content = "It didn't dawn on me until I saw the butterfly stickers today... This is actually where you and Lorelei were from, isn't it?",
  ui_story_5058_50580801_18_dialog_content = "The very village cursed by the Denuo Goddess, as you elaborated back then...",
  ui_story_5058_50580801_19_dialog_content = "The hype about the Goddess throughout the park is giving me the feeling something is about to take Lorelei away...",
  ui_story_5058_50580801_20_dialog_content = "\"Cursed by the Denuo Goddess\"... How can you put that so lightly?",
  ui_story_5058_50580801_21_dialog_content = "I never wanted to mention the village.",
  ui_story_5058_50580801_22_dialog_content = "Even as I set my foot back on this soil again, its past destruction still haunts me...",
  ui_story_5058_50580801_23_dialog_content = "But when I saw how determined and dedicated Lorelei was to gradually turn the valley around, I finally also saw hope...",
  ui_story_5058_50580801_24_dialog_content = "So you admit you're helping Lorelei rebuild your home?",
  ui_story_5058_50580801_25_dialog_content = "Does she know you were the one who saved her?",
  ui_story_5058_50580801_26_dialog_content = "...",
  ui_story_5058_50580801_27_dialog_content = "And that's the comprehensive plan for the resort and greenizing the whole canyon. What do you think?",
  ui_story_5058_50580801_28_dialog_content = "That is not a plan, young lady.",
  ui_story_5058_50580801_29_dialog_content = "Restoring nature, immortalizing the experience of going to the park with parents... It's just a waste of my time.",
  ui_story_5058_50580801_30_dialog_content = "Listen to me, Honcho Sinsa, I promise the best pay for everyone working on the project!",
  ui_story_5058_50580801_31_dialog_content = "As many skilled people Rediesel Wrench has, they need a stage to show off...",
  ui_story_5058_50580801_32_dialog_content = "There's nothing to discuss. Us working for someone else? Not a chance...",
  ui_story_5058_50580801_33_dialog_content = "I'm interested. Maybe I can help.",
  ui_story_5058_50580801_34_dialog_content = "Hey, aren't you Cena?",
  ui_story_5058_50580801_35_dialog_content = "You still remember me?",
  ui_story_5058_50580801_36_dialog_content = "Don't tell me you're long-lost siblings or something like that!",
  ui_story_5058_50580801_37_dialog_content = "Of course I remember you. How can I forget the person who saved me?",
  ui_story_5058_50580801_38_dialog_content = "Where did you go? I kept hoping I could see you again.",
  ui_story_5058_50580801_39_dialog_content = "...",
  ui_story_5058_50580801_40_dialog_content = "I understand. Mom probably didn't want you around me.",
  ui_story_5058_50580801_41_dialog_content = "But it's so good to see you again!",
  ui_story_5058_50580801_42_dialog_content = "Ahem... Sorry, almost forgot I came here on business.",
  ui_story_5058_50580801_43_dialog_content = "Let's start over. My name is Lorelei Cardogon. Nice to meet you!",
  ui_story_5058_50580801_44_dialog_content = "Oh, and don't tell mom I still remember you.",
  ui_story_5058_50580801_45_dialog_content = "Sure. Good luck with the deal.",
  ui_story_5058_50580801_46_dialog_content = "Wait, you mentioned you want to help, but I'm very strict when it comes to hiring.",
  ui_story_5058_50580801_47_dialog_content = "You'll have to pass an evaluation before you can start!",
  ui_story_5058_50580801_48_dialog_content = "Hey, is that how you treat someone who saved you?",
  ui_story_5058_50580801_49_dialog_content = "Hmm, you turn out to be an interesting one, Lorelei. Maybe I can design a few rides for you too.",
  ui_story_5058_50580801_50_dialog_content = "That'll be great, Honcho Sinsa! I knew Rediesel Desert is actually a cool place.",
  ui_story_5058_50580801_51_dialog_content = "Don't you worry, I didn't say a thing. To her, I'm just an employee.",
  ui_story_5058_50580801_52_dialog_content = "And please relax, Lorelei is a great kid. You're worrying about things that won't happen.",
  ui_story_5058_50580801_53_dialog_content = "Won't happen? So what were those Eclipsites?",
  ui_story_5058_50580801_54_dialog_content = "Wow, the stress I'm feeling... Don't you believe she can handle it? Or...",
  ui_story_5058_50580801_55_dialog_content = "Are you afraid if she resolved this crisis, she would stand on her feet enough to... leave you?",
  ui_story_5058_50580801_56_dialog_content = "Hmm, I even wonder if you deliberately brought the Eclipsites...",
  ui_story_5058_50580801_57_dialog_content = "And let them hurt my child? Is that something a mother would do?",
  ui_story_5058_50580801_58_dialog_content = "I've always treated her as my own. Why wouldn't I want to see her succeed?",
  ui_story_5058_50580801_59_dialog_content = "Stand on her feet... Run her own life...",
  ui_story_5058_50580801_60_dialog_content = "I know that's going to happen sooner or later.",
  ui_story_5058_50580801_61_dialog_content = "All I can hope for is it's later so I can pave the way better for her...",
  ui_story_5058_50580801_62_dialog_content = "Heh, so understanding yet so hard to let it go!",
  ui_story_5058_50580801_63_dialog_content = "<size=45>Graaagh!</size>",
  ui_story_5058_50580801_64_dialog_content = "We'll talk about that later. Let's finish off the Eclipsites first, Ms. Shashona.",
  ui_story_5058_50580802_1_dialog_content = "Done.",
  ui_story_5058_50580802_2_dialog_content = "You really are a deadeye, Ms. Shashona.",
  ui_story_5058_50580802_3_dialog_content = "Wait... This feeling... It's the same as before...",
  ui_story_5058_50580802_4_dialog_content = "Could it be...",
  ui_story_5058_50580802_5_dialog_content = "What are you saying, Cena?",
  ui_story_5058_50580802_6_dialog_content = "Nah, can't be, it's all cleared...",
  ui_story_5058_50580802_7_dialog_content = "Sorry, Ms. Shashona, I can't walk you back. Something just came up.",
  ui_story_5058_50580802_8_dialog_content = "Where are you going?",
  ui_story_5058_50580802_9_dialog_content = "You know the valley and Lorelei are in danger, right?",
  ui_story_5058_50580802_10_dialog_content = "<size=45>Hey...!</size>",
  ui_story_5058_50580901_1_dialog_content = "You're back, Lorelei! How's it look out there?",
  ui_story_5058_50580901_2_dialog_content = "No sign of Eclipsites for now, but still have no clue why they would suddenly intrude...",
  ui_story_5058_50580901_3_dialog_content = "What's going on with the guests?",
  ui_story_5058_50580901_4_dialog_content = "We helped all of them to their rooms, but the manager and Shashona are nowhere to be seen...",
  ui_story_5058_50580901_5_dialog_content = "Cena and my mom? Did you check every corner of the hotel?",
  ui_story_5058_50580901_6_dialog_content = "Yes, everywhere.",
  ui_story_5058_50580901_7_dialog_content = "Thanks for letting me know, Bopper. Please tell the security team to set up defenses around the hotel.",
  ui_story_5058_50580901_8_dialog_content = "Also, remind the staff to prepare and deliver meals to the guests on time, not a second late...",
  ui_story_5058_50580901_9_dialog_content = "Roar!",
  ui_story_5058_50580901_10_dialog_content = "What?",
  ui_story_5058_50580901_11_dialog_content = "Ice Blossom!",
  ui_story_5058_50580901_12_dialog_content = "Wow, what lightning reflexes, Carleen! You killed the Eclipsite before I even knew it was there!",
  ui_story_5058_50580901_13_dialog_content = "But how did they get...",
  ui_story_5058_50580901_14_dialog_content = "Inside... the hotel...",
  ui_story_5058_50580901_15_dialog_content = "Lorelei...? You...",
  ui_story_5058_50580901_16_dialog_content = "My eyes... can't keep them open...",
  ui_story_5058_50580901_17_dialog_content = "PlayerName...",
  ui_story_5058_50580901_18_dialog_content = "...",
  ui_story_5058_50580901_19_dialog_content = "Vice... Carleen...?!",
  ui_story_5058_50580901_20_dialog_content = "What's... going on...",
  ui_story_5058_50580901_21_dialog_content = "PlayerName... PlayerName?",
  ui_story_5058_50580901_22_dialog_content = "Huh?",
  ui_story_5058_50580901_23_dialog_content = "Found you! Little troublemaker! Time to come home with Mommy for dinner. You know people gotta eat to grow, right?",
  ui_story_5058_50580901_24_dialog_content = "Another dream?",
  ui_story_5058_50580901_25_dialog_content = "Again? This time, though...",
  ui_story_5058_50580901_26_option_content = "Come on, wake up!",
  ui_story_5058_50580901_27_dialog_content = "Huff... What just happened? It felt exactly the same as when I passed out in the valley.",
  ui_story_5058_50580901_28_dialog_content = "Everybody is out...",
  ui_story_5058_50580901_29_dialog_content = "Lorelei? Lorelei! Wake up!",
  ui_story_5058_50580901_30_dialog_content = "Mom... mom...",
  ui_story_5058_50580901_31_dialog_content = "Vice! Carleen!",
  ui_story_5058_50580901_32_dialog_content = "Gotta cook... make new dishes...",
  ui_story_5058_50580901_33_dialog_content = "...",
  ui_story_5058_50580901_34_dialog_content = "Is everyone in a trance? Hey, what's that flashing in the air?",
  ui_story_5058_50580901_35_dialog_content = "It's everywhere, all throughout the hotel! Is it what knocked people out?",
  ui_story_5058_50580901_36_dialog_content = "What am I going to do? I can wake them up telepathically... No, open the window and let the fresh air in.",
  ui_story_5058_50580901_37_dialog_content = "But then, won't the Eclipsites outside be able to come in?",
  ui_story_5058_50580901_38_dialog_content = "Hmm, didn't Lorelei mention a ventilation system? Let's turn that on!",
  ui_story_5058_50580901_39_dialog_content = "The problem is, I don't know where the switch is.",
  ui_story_5058_50580901_40_dialog_content = "Lorelei would know for sure! Yes, I shall wake her up first!",
  ui_story_5058_50580901_41_option_content = "Force Boost!",
  ui_story_5058_50580901_42_dialog_content = "Are you asleep, Lorelei?",
  ui_story_5058_50580901_43_dialog_content = "No, I'm just listening to Mom telling me a story with my eyes closed!",
  ui_story_5058_50580901_44_dialog_content = "(This must be Lorelei's memory.)",
  ui_story_5058_50580901_45_dialog_content = "(Is that little girl Lorelei? But her mom doesn't look like Shashona!)",
  ui_story_5058_50580901_46_dialog_content = "(And that young guy over there is the figure I saw when I passed out in the valley!)",
  ui_story_5058_50580901_47_dialog_content = "Legend has it that Denuo Valley is free of Eclipsites because we're under the <color=#FFB400>Denuo Goddess</color>' protection.",
  ui_story_5058_50580901_48_dialog_content = "Butterflies? You mean the ones around us?",
  ui_story_5058_50580901_49_dialog_content = "The Denuo Goddesses aren't ordinary butterflies. They got wings as shiny as diamonds.",
  ui_story_5058_50580901_50_dialog_content = "Everyone who sees a Goddess will receive the blessing of unparalleled revelation and joy.",
  ui_story_5058_50580901_51_dialog_content = "Really? When do I get to see one?",
  ui_story_5058_50580901_52_dialog_content = "Oh child, it's not easy to see a Goddess.",
  ui_story_5058_50580901_53_dialog_content = "Story has it they live in Denuo Valley but hardly avail themselves to anyone.",
  ui_story_5058_50580901_54_dialog_content = "I think I saw a young Denuo Goddess a few days ago.",
  ui_story_5058_50580901_55_dialog_content = "I couldn't get my eyes off that brilliant glow from its wings... Just one look and you'll never forget!",
  ui_story_5058_50580901_56_dialog_content = "I heard young Denuo Goddess rarely grew to maturity and it was trapped in a spiderweb, so I freed it.",
  ui_story_5058_50580901_57_dialog_content = "Wow! So did you receive the blessing?",
  ui_story_5058_50580901_58_dialog_content = "Maybe not...?",
  ui_story_5058_50580901_59_dialog_content = "Come on, Cena, don't tell me you've never actually seen one! It's not good to lie!",
  ui_story_5058_50580901_60_dialog_content = "(That young man is actually Cena? So they knew each other before?)",
  ui_story_5058_50580901_61_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh!</color>",
  ui_story_5058_50580901_62_dialog_content = "Mom! Cena! Where are you?",
  ui_story_5058_50580901_63_dialog_content = "Sandstorm! It's engulfing the whole village!",
  ui_story_5058_50580901_64_dialog_content = "We deserve it for angering the Denuo Goddess!",
  ui_story_5058_50580901_65_dialog_content = "Mom... Don't leave me behind...",
  ui_story_5058_50580901_66_dialog_content = "Grab my hand, Lorelei!",
  ui_story_5058_50580901_67_dialog_content = "Cena...?",
  ui_story_5058_50580901_68_dialog_content = "It's me, PlayerName!",
  ui_story_5058_50580901_69_dialog_content = "PlayerName...?",
  ui_story_5058_50580901_70_option_content = "Wake up!",
  ui_story_5058_50580901_71_dialog_content = "Huh...?",
  ui_story_5058_50580901_72_dialog_content = "You're finally awake, Lorelei! Don't freak out, it's just me!",
  ui_story_5058_50580901_73_dialog_content = "PlayerName? What happened?",
  ui_story_5058_50580901_74_dialog_content = "I don't know, but everyone just passed out suddenly.",
  ui_story_5058_50580901_75_dialog_content = "Then I noticed there was something weird in the air.",
  ui_story_5058_50580901_76_dialog_content = "Something that kept flickering.",
  ui_story_5058_50580901_77_dialog_content = "They must be related to everybody going unconscious. If we turned on the ventilation system you mentioned, would it get rid of those things?",
  ui_story_5058_50580901_78_dialog_content = "The switch is close by. Follow me!",
  ui_story_5058_50580901_79_dialog_content = "Graagh!",
  ui_story_5058_50580901_80_dialog_content = "More Eclipsites?",
  ui_story_5058_50580901_81_dialog_content = "Just the two of us left... Lend me a hand, PlayerName!",
  ui_story_5058_50581001_1_dialog_content = "Graaaah!",
  ui_story_5058_50581001_2_dialog_content = "Ahhhh!",
  ui_story_5058_50581001_3_dialog_content = "You can't kill me like that!",
  ui_story_5058_50581001_4_dialog_content = "Not to mention this life isn't my own now so, sorry, can't let you have it!",
  ui_story_5058_50581001_5_dialog_content = "But very soon, when I see <color=#FFB400>\"her\"</color>... On the other hand, \"she\" probably drew you here.",
  ui_story_5058_50581001_6_dialog_content = "I still want to see \"her\", though, and repent personally...",
  ui_story_5058_50581001_7_dialog_content = "(Has Cena gone insane? Who is it he wants to see?)",
  ui_story_5058_50581001_8_dialog_content = "Roar!",
  ui_story_5058_50581001_9_dialog_content = "Watch out!",
  ui_story_5058_50581001_10_dialog_content = "Ms. Shashona?",
  ui_story_5058_50581001_11_dialog_content = "What are you doing, Cena? Why are you trying to be a hero when you should be back at the hotel helping Lorelei?",
  ui_story_5058_50581001_12_dialog_content = "This has nothing to do with you. I must face what's been bothering me for the better part of my life alone. I have to do it by myself...",
  ui_story_5058_50581001_13_dialog_content = "Thank you for raising and looking after Lorelei for me...",
  ui_story_5058_50581001_14_dialog_content = "She's an adult now. You should listen to what she has to say, stop dictating everything for her.",
  ui_story_5058_50581001_15_dialog_content = "That's it. Please turn back.",
  ui_story_5058_50581001_16_dialog_content = "Are you giving me your last words?",
  ui_story_5058_50581001_17_dialog_content = "Gaaaaaah!",
  ui_story_5058_50581001_18_dialog_content = "Come on, come at me!",
  ui_story_5058_50581001_19_dialog_content = "Charging the Eclipsites just like that? Have you lost your mind, Cena?!",
  ui_story_5058_50581001_20_dialog_content = "This is giving me a headache.",
  ui_story_5058_50581001_21_dialog_content = "Unfortunately, I'm not one to stand by and watch someone else die.",
  ui_story_5058_50581001_22_dialog_content = "All right, come taste my new custom bullets and see if you like them!",
  ui_story_5058_50581001_23_dialog_content = "<color=#e8d9bb>Bang! Bang! Bang!</color>",
  ui_story_5058_50581001_24_dialog_content = "Ugh!",
  ui_story_5058_50581001_25_dialog_content = "I beg you, Shashona, leave me alone...",
  ui_story_5058_50581001_26_dialog_content = "Leave you alone? How come that always rolled so easily off both your and Lorelei's tongue?",
  ui_story_5058_50581001_27_dialog_content = "Lorelei and I are different. You still don't get it. She never wanted to get away from you.",
  ui_story_5058_50581001_28_dialog_content = "The reason she wanted to build an amusement park is because she cherished the memories of you taking her there.",
  ui_story_5058_50581001_29_dialog_content = "Is that what she told you? That child...",
  ui_story_5058_50581001_30_dialog_content = "I know that. I figured it out when I read her business plan. I was just...",
  ui_story_5058_50581001_31_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_32_dialog_content = "The wind is blowing in the valley...?",
  ui_story_5058_50581001_33_dialog_content = "<size=45><color=#e8d9bb>Hiss—</color></size>",
  ui_story_5058_50581001_34_dialog_content = "Coming...",
  ui_story_5058_50581001_35_dialog_content = "\"She\" is coming!",
  ui_story_5058_50581001_36_dialog_content = "Who is coming?",
  ui_story_5058_50581001_37_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_38_dialog_content = "Hiss—Hiss—",
  ui_story_5058_50581001_39_dialog_content = "<color=#FFB400>Denuo Goddess</color>... Finally, I see you!",
  ui_story_5058_50581001_40_dialog_content = "I fled the village and spent half of my life wandering all over Astra only to realize...",
  ui_story_5058_50581001_41_dialog_content = "My heart had never left Denuo!",
  ui_story_5058_50581001_42_dialog_content = "I see you've come for your revenge, Denuo Goddess.",
  ui_story_5058_50581001_43_dialog_content = "Yes, I shouldn't have survived. I thought I could earn amnesty by rebuilding the valley...",
  ui_story_5058_50581001_44_dialog_content = "Please deal me the final punishment!",
  ui_story_5058_50581001_45_dialog_content = "Is that the Denuo Goddess that inflicted the curse?",
  ui_story_5058_50581001_46_dialog_content = "Calm down, Cena! It's just a larger than usual butterfly!",
  ui_story_5058_50581001_47_dialog_content = "I don't believe a mere butterfly can run our lives!",
  ui_story_5058_50581001_48_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581001_49_dialog_content = "Hiss!",
  ui_story_5058_50581001_50_dialog_content = "What is it releasing?",
  ui_story_5058_50581001_51_dialog_content = "Gahhhh!",
  ui_story_5058_50581001_52_dialog_content = "More Eclipsites are showing up...",
  ui_story_5058_50581001_53_dialog_content = "I get it, the butterfly led the Eclipsites to the valley! Cena!",
  ui_story_5058_50581001_54_dialog_content = "Cena?",
  ui_story_5058_50581001_55_dialog_content = "Please punish me...",
  ui_story_5058_50581001_56_dialog_content = "Get on your feet now and fight the Eclipsites!",
  ui_story_5058_50581002_1_dialog_content = "Gah...",
  ui_story_5058_50581002_2_dialog_content = "I'm dizzy... What's going on...? Can't hold on...",
  ui_story_5058_50581002_3_dialog_content = "Cena... Cena...",
  ui_story_5058_50581002_4_dialog_content = "Run... Run...",
  ui_story_5058_50581002_5_dialog_content = "Huh?",
  ui_story_5058_50581002_6_dialog_content = "Run...",
  ui_story_5058_50581002_7_dialog_content = "Run...",
  ui_story_5058_50581002_8_dialog_content = "Why did you save me? People like me aren't worth the effort...",
  ui_story_5058_50581002_9_dialog_content = "Run... Take Lorelei and... run...!",
  ui_story_5058_50581002_10_dialog_content = "...",
  ui_story_5058_50581002_11_dialog_content = "Oh...",
  ui_story_5058_50581002_12_dialog_content = "Ms. Shashona?!",
  ui_story_5058_50581002_13_dialog_content = "Coco, Shashona... Why would you both save someone who never treated life seriously like me?",
  ui_story_5058_50581002_14_dialog_content = "<size=45>Hiss, hiss, hiss!</size>",
  ui_story_5058_50581002_15_dialog_content = "Growl!",
  ui_story_5058_50581002_16_dialog_content = "But I'm the one who shouldn't be forgiven, not Shashona...",
  ui_story_5058_50581002_17_dialog_content = "Ms. Shashona! Can you hear me?! Shashona!",
  ui_story_5058_50581002_18_dialog_content = "No...",
  ui_story_5058_50581002_19_dialog_content = "<color=#e8d9bb>*Crash*</color>",
  ui_story_5058_50581002_20_dialog_content = "Come here, Shashona! Where did your mom go?",
  ui_story_5058_50581002_21_dialog_content = "I don't know...",
  ui_story_5058_50581002_22_dialog_content = "Stop crying! You don't know? How come you don't know? Your mom ran away, got that?! It's all your fault!",
  ui_story_5058_50581002_23_dialog_content = "*Sobbing*",
  ui_story_5058_50581002_24_dialog_content = "Where did she keep the money?",
  ui_story_5058_50581002_25_dialog_content = "Daddy... Our store's in debt. Mom said we must save every penny, not for you to blow it on booze.",
  ui_story_5058_50581002_26_dialog_content = "Why do you still listen to her when she doesn't even want you anymore? I see you need a good beating!",
  ui_story_5058_50581002_27_dialog_content = "<color=#e8d9bb>Smack! Smack!</color>",
  ui_story_5058_50581002_28_dialog_content = "...",
  ui_story_5058_50581002_29_dialog_content = "Poor child... Don't worry, I promise to nurse you back to health.",
  ui_story_5058_50581002_30_dialog_content = "From the first time I saw you I knew you're the daughter sent to me from above, making up for my childhood...",
  ui_story_5058_50581002_31_dialog_content = "I crawled out of the quagmire bit by bit only after all the years of nightmare.",
  ui_story_5058_50581002_32_dialog_content = "Starting now, I'll make you the happiest girl in the world, never to be hurt again.",
  ui_story_5058_50581002_33_dialog_content = "<color=#e8d9bb>Pitter-patter...</color>",
  ui_story_5058_50581002_34_dialog_content = "Where am I?",
  ui_story_5058_50581002_35_dialog_content = "Lorelei, my baby, come out of the rain to me!",
  ui_story_5058_50581002_36_dialog_content = "Why would you let me come under your umbrella?",
  ui_story_5058_50581002_37_dialog_content = "Because... I've been out in the rain when I was a child and that didn't feel good.",
  ui_story_5058_50581002_38_dialog_content = "So I don't want you to get rained on or get hurt. I want you to worry about nothing but growing up safe and sound.",
  ui_story_5058_50581002_39_dialog_content = "But who are you? Why are you this good to me?",
  ui_story_5058_50581002_40_dialog_content = "Did you forget I'm your mom? You got daddy and a little brother too. We're the happiest family in the world.",
  ui_story_5058_50581002_41_dialog_content = "Is there anything you want, precious? I can fulfill your every wish!",
  ui_story_5058_50581002_42_dialog_content = "Can I read story books?",
  ui_story_5058_50581002_43_dialog_content = "Yes!",
  ui_story_5058_50581002_44_dialog_content = "Can I wear pretty dresses?",
  ui_story_5058_50581002_45_dialog_content = "Yes!",
  ui_story_5058_50581002_46_dialog_content = "And... and...",
  ui_story_5058_50581002_47_dialog_content = "I can take you to the new amusement park!",
  ui_story_5058_50581002_48_dialog_content = "Amusement park! Can I go? Will daddy and brother go with us too?",
  ui_story_5058_50581002_49_dialog_content = "Yes. We can go first since daddy is abroad on business and your brother is in school. We can all go many times when they're back.",
  ui_story_5058_50581002_50_dialog_content = "Can I run a business like daddy?",
  ui_story_5058_50581002_51_dialog_content = "That's too risky for you, baby. I've been through a lot and suffered a lot to get where I am now.",
  ui_story_5058_50581002_52_dialog_content = "So I don't want my baby to go through the same things...",
  ui_story_5058_50581002_53_dialog_content = "Okay... Hey, I wonder what's that fun thing over there...",
  ui_story_5058_50581002_54_dialog_content = "Slow down, baby.",
  ui_story_5058_50581002_55_dialog_content = "<color=#e8d9bb>Whoosh—</color>",
  ui_story_5058_50581002_56_dialog_content = "My umbrella got blown away...",
  ui_story_5058_50581002_57_dialog_content = "It's okay, Mom! See, I found a pretty umbrella that's even bigger than yours!",
  ui_story_5058_50581002_58_dialog_content = "I can hold it up for you too!",
  ui_story_5058_50581002_59_dialog_content = "Sigh...",
  ui_story_5058_50581002_60_dialog_content = "The rain is about to stop. I wanna go there!",
  ui_story_5058_50581002_61_dialog_content = "Where are you, my baby?",
  ui_story_5058_50581002_62_dialog_content = "Precious? Laurie!<size=45>Lorelei!</size>",
  ui_story_5058_50581002_63_dialog_content = "Don't leave me... Don't abandon me...",
  ui_story_5058_50581002_64_dialog_content = "Wait, how come I said that?",
  ui_story_5058_50581002_65_dialog_content = "I see, it's because I can't be apart from you...",
  ui_story_5058_50581002_66_dialog_content = "It's me who needed you around...",
  ui_story_5058_50581101_1_dialog_content = "<color=#e8d9bb>Click!</color>",
  ui_story_5058_50581101_2_dialog_content = "Okay, the ventilation system's working.",
  ui_story_5058_50581101_3_dialog_content = "But why is that door open?",
  ui_story_5058_50581101_4_dialog_content = "Isn't it usually closed?",
  ui_story_5058_50581101_5_dialog_content = "There's a basement here just for air conditioners.",
  ui_story_5058_50581101_6_dialog_content = "You keep air conditioners underground?",
  ui_story_5058_50581101_7_dialog_content = "Just the main system. The pipes connect to the outdoors.",
  ui_story_5058_50581101_8_dialog_content = "Because it takes up a lot of space and is very noisy, I was trying to figure out exactly where to put it even before building the hotel.",
  ui_story_5058_50581101_9_dialog_content = "Until Cena suggested digging a basement for it. This is his jurisdiction, too.",
  ui_story_5058_50581101_10_dialog_content = "We couldn't find Cena and Shashona at all. Could they be in the basement?",
  ui_story_5058_50581101_11_dialog_content = "Boss, PlayerName... Why is everybody out?",
  ui_story_5058_50581101_12_dialog_content = "Bopper? You're up!",
  ui_story_5058_50581101_13_dialog_content = "But they're still...",
  ui_story_5058_50581101_14_dialog_content = "Please go wake everybody up, Bopper, then check on the guests.",
  ui_story_5058_50581101_15_dialog_content = "PlayerName and I will go to the basement to see if Cena is down there.",
  ui_story_5058_50581101_16_dialog_content = "Sure!",
  ui_story_5058_50581101_17_dialog_content = "Hmm, I think I heard footsteps in the basement. Is that Mr. Cena?",
  ui_story_5058_50581101_18_dialog_content = "Maybe?",
  ui_story_5058_50581101_19_dialog_content = "<color=#e8d9bb>Thump, thump, thump!</color>",
  ui_story_5058_50581101_20_dialog_content = "Graagh!",
  ui_story_5058_50581102_1_dialog_content = "<size=45>Cena? Mom? Are you there?</size>",
  ui_story_5058_50581102_2_dialog_content = "You there...?",
  ui_story_5058_50581102_X2_dialog_content = "Are you there?",
  ui_story_5058_50581102_X3_dialog_content = "... Right?",
  ui_story_5058_50581102_3_dialog_content = "No wonder the Eclipsites could slip into the hotel. This is obviously a tunnel and who knows where it leads to.",
  ui_story_5058_50581102_4_dialog_content = "When I left the basement to Cena, I never expected him to dig a tunnel behind my back.",
  ui_story_5058_50581102_5_dialog_content = "I see a lot of tables, chairs, bottles and cans around here, but they seem to be very old.",
  ui_story_5058_50581102_6_dialog_content = "Very old? Don't tell me...",
  ui_story_5058_50581102_7_dialog_content = "Is that a stack of files under the stool?",
  ui_story_5058_50581102_8_dialog_content = "Let me see...",
  ui_story_5058_50581102_9_dialog_content = "\"Formula for Denuo Incense?\"",
  ui_story_5058_50581102_10_dialog_content = "I only spoke to Cena about it this morning, but has he been looking into it before, or...",
  ui_story_5058_50581102_11_dialog_content = "It says the most vital component for the incense is the... <color=#FFB400>Denuo Goddess</color>?!",
  ui_story_5058_50581102_12_dialog_content = "What?!",
  ui_story_5058_50581102_13_dialog_content = "And the documents belonged to... Denuo Village.",
  ui_story_5058_50581102_14_dialog_content = "Is this the vestige of Denuo Village? But I didn't know the villagers used to make incense out of Denuo Goddesses.",
  ui_story_5058_50581102_15_dialog_content = "No way Cena didn't know about it, but how come he never told me?",
  ui_story_5058_50581102_16_dialog_content = "Were you and Cena from the village?",
  ui_story_5058_50581102_17_dialog_content = "Sorry, I happened to catch a snippet of your dream when I tried to wake you up.",
  ui_story_5058_50581102_18_dialog_content = "Then I guess you also found out Shashona isn't my biological mother.",
  ui_story_5058_50581102_19_dialog_content = "But it's all right, PlayerName, I didn't mean to cover up my past.",
  ui_story_5058_50581102_20_dialog_content = "I'm just concerned that bringing it up might make my mom Shashona feel bad.",
  ui_story_5058_50581102_21_dialog_content = "And you saw how good she is to me too, and did a lot for me, so I shouldn't be holding on to the past like I am now.",
  ui_story_5058_50581102_22_dialog_content = "But those memories, happy or sad, would still pop up once in a while.",
  ui_story_5058_50581102_23_dialog_content = "So, you did know Cena from way back?",
  ui_story_5058_50581102_24_dialog_content = "He was our neighbor. I called him Mr. Cena.",
  ui_story_5058_50581102_25_dialog_content = "One day, an unprecedented sandstorm hit Denuo. I saw it destroying the whole village with my own eyes.",
  ui_story_5058_50581102_26_dialog_content = "I got hurt in the disaster, but I remember it was Cena who saved me.",
  ui_story_5058_50581102_27_dialog_content = "And also vaguely how he handed me to my foster mom...",
  ui_story_5058_50581102_28_dialog_content = "I thought he'd make time to see me, but he never did until a chance meeting right before building the resort.",
  ui_story_5058_50581102_29_dialog_content = "Actually, when I passed out in the valley before, I saw the young Cena's face in a dream for some reason.",
  ui_story_5058_50581102_30_dialog_content = "The underground tunnel, Denuo incense, Eclipsites, that weird thing in the air, and the Denuo Goddess...",
  ui_story_5058_50581102_31_dialog_content = "Cena is the key to all that.",
  ui_story_5058_50581102_32_dialog_content = "Time has changed him into someone I don't fully recognize.",
  ui_story_5058_50581102_33_dialog_content = "But I'm still willing to trust him, the big brother who saved me in the disaster.",
  ui_story_5058_50581102_34_dialog_content = "What is he up to, though?",
  ui_story_5058_50581102_35_dialog_content = "<color=#e8d9bb>Thump, thump, thump...</color>",
  ui_story_5058_50581102_36_dialog_content = "Who's there? Is that an Eclipsite?",
  ui_story_5058_50581102_37_dialog_content = "It's me...",
  ui_story_5058_50581102_38_dialog_content = "Cena.",
  ui_story_5058_50581201_1_dialog_content = "Sigh, you discovered this place.",
  ui_story_5058_50581201_2_dialog_content = "You read the files, I see...",
  ui_story_5058_50581201_3_dialog_content = "I have a lot of questions for you.",
  ui_story_5058_50581201_4_dialog_content = "Wait, is Cena carrying someone on his back?",
  ui_story_5058_50581201_X4_dialog_content = "... It's Shashona!",
  ui_story_5058_50581201_5_dialog_content = "Mom?!",
  ui_story_5058_50581201_6_dialog_content = "What did you do to my mother, Cena?!",
  ui_story_5058_50581201_7_dialog_content = "I...",
  ui_story_5058_50581201_8_dialog_content = "Graah!!",
  ui_story_5058_50581201_9_dialog_content = "Heh, they still caught up.",
  ui_story_5058_50581201_10_dialog_content = "Let's dispose of the Eclipsites first, Lorelei!",
  ui_story_5058_50581202_1_dialog_content = "Bopper said you and Lorelei went down to the basement but never returned, PlayerName. Carleen and I were just about to go check on you!",
  ui_story_5058_50581202_2_dialog_content = "Is there any other Eclipsite down there? Are you okay?",
  ui_story_5058_50581202_3_dialog_content = "Oh, Vice, Carleen... Thank goodness you're awake.",
  ui_story_5058_50581202_4_dialog_content = "There's a passage to the heart of the valley in the basement but we sealed it off, so there shouldn't be any more Eclipsite.",
  ui_story_5058_50581202_5_dialog_content = "A passage in the basement...?",
  ui_story_5058_50581202_6_dialog_content = "How are the guests, Bopper?",
  ui_story_5058_50581202_7_dialog_content = "They've all woken up from the coma, but... some of them are asking for that thing in the air.",
  ui_story_5058_50581202_8_dialog_content = "They said they felt good after inhaling it and wanted to go into the same coma again!",
  ui_story_5058_50581202_9_dialog_content = "My sentiment exactly. It might be a coma, but I woke up astonishingly refreshed.",
  ui_story_5058_50581202_10_dialog_content = "Me too! My body felt light and fluffy like I was flying...",
  ui_story_5058_50581202_11_dialog_content = "If I'm correct, that thing probably has a connection to the Denuo Goddess.",
  ui_story_5058_50581202_12_dialog_content = "Or should I say to you... Cena?",
  ui_story_5058_50581202_13_dialog_content = "...",
  ui_story_5058_50581202_14_dialog_content = "General manager Cena?! We were looking all over for you! You were in the basement too?",
  ui_story_5058_50581202_15_dialog_content = "Tell the guests there's nothing in the air and sell them that it was all a hallucination, Bopper.",
  ui_story_5058_50581202_16_dialog_content = "The addiction will stop a few days after they get home.",
  ui_story_5058_50581202_17_dialog_content = "That thing causes addictions?",
  ui_story_5058_50581202_18_dialog_content = "Agh...",
  ui_story_5058_50581202_19_dialog_content = "Shashona? Did the Eclipsites hurt her? I'll get a doctor right away...",
  ui_story_5058_50581202_20_dialog_content = "It's okay, Bopper. The average doctor can't help, anyway.",
  ui_story_5058_50581202_21_dialog_content = "Mind telling me what happened to my mom now, Cena?",
  ui_story_5058_50581202_22_dialog_content = "You were right, Lorelei, this all happened because of me.",
  ui_story_5058_50581202_23_dialog_content = "I went off to find the Denuo Goddess in the valley, but failed to notice Ms. Shashona was following me.",
  ui_story_5058_50581202_24_dialog_content = "Then, we did run into the Goddess. Or more precisely, a matured Goddess.",
  ui_story_5058_50581202_25_dialog_content = "The Denuo Goddess?! The story is real? Did you get any blessings?",
  ui_story_5058_50581202_26_dialog_content = "There were never any blessings or protection.",
  ui_story_5058_50581202_X26_dialog_content = "She roared, flapped her wings and whipped up a storm. If she left any \"gift\"...",
  ui_story_5058_50581202_27_dialog_content = "It's the <color=#FFB400>powder</color> she released. A lot of powder, at that, enough to get into the hotel through the underground passage.",
  ui_story_5058_50581202_28_dialog_content = "Powder? You mean the stuff that sparkled in the air?",
  ui_story_5058_50581202_29_dialog_content = "Yes. The powder is a neuro substance that causes coma, hallucination or memory recall.",
  ui_story_5058_50581202_30_dialog_content = "I've had certain immunity to it since childhood, but not Ms. Shashona...",
  ui_story_5058_50581202_31_dialog_content = "She inhaled too much <color=#FFB400>powder</color> trying to save me.",
  ui_story_5058_50581202_32_dialog_content = "But all the powder is gone now, why isn't my mom waking up?",
  ui_story_5058_50581202_33_dialog_content = "Didn't you wake me up with your psychic ability, PlayerName? Can you save my mom, please?",
  ui_story_5058_50581202_34_dialog_content = "Sure, I'll try.",
  ui_story_5058_50581202_35_option_content = "Force Boost!",
  ui_story_5058_50581202_36_dialog_content = "<color=#e8d9bb>Pitter-patter, pitter-patter...</color>",
  ui_story_5058_50581202_37_dialog_content = "Is it raining?",
  ui_story_5058_50581202_38_dialog_content = "*Sob*",
  ui_story_5058_50581202_39_dialog_content = "Where are you, Shashona?",
  ui_story_5058_50581202_40_dialog_content = "Is her dream crumbling?",
  ui_story_5058_50581202_41_dialog_content = "<size=45>Answer me, Shashona!</size>",
  ui_story_5058_50581202_42_dialog_content = "*Sob*",
  ui_story_5058_50581202_43_dialog_content = "Where is that voice coming from?",
  ui_story_5058_50581202_44_dialog_content = "So cold... If this keeps up...",
  ui_story_5058_50581202_45_dialog_content = "I'm gonna be...",
  ui_story_5058_50581202_46_dialog_content = "<color=#e8d9bb>Slap!</color>",
  ui_story_5058_50581202_47_dialog_content = "What the...",
  ui_story_5058_50581202_48_dialog_content = "It's all good, he's back.",
  ui_story_5058_50581202_49_dialog_content = "Oh, my face... That hurt.",
  ui_story_5058_50581202_50_dialog_content = "Stop scaring us like that, PlayerName. We couldn't get a response from you!",
  ui_story_5058_50581202_51_dialog_content = "So I had to resort to slapping. Luckily, it worked.",
  ui_story_5058_50581202_52_dialog_content = "So how is it?",
  ui_story_5058_50581202_53_dialog_content = "Her dream was crumbling and I couldn't find her at all... I'm sorry.",
  ui_story_5058_50581202_54_dialog_content = "I guess she took in more powder than I thought.",
  ui_story_5058_50581202_55_dialog_content = "Don't freak me out like this, Mom... Wake up!",
  ui_story_5058_50581202_56_dialog_content = "We still haven't hung out in our own park, and a lot of other things left to do together...",
  ui_story_5058_50581202_57_dialog_content = "Why did you insist on finding the Denuo Goddess, Cena?",
  ui_story_5058_50581202_58_dialog_content = "The tunnel in the basement and the odd files... I believe you owe Lorelei an explanation.",
  ui_story_5058_50581202_59_dialog_content = "There were some things I never got the chance to tell you before, Lorelei.",
  ui_story_5058_50581202_60_dialog_content = "Because you were still too young to understand them then.",
  ui_story_5058_50581202_61_dialog_content = "Even to this day, I struggled over whether to reveal the truth to you.",
  ui_story_5058_50581202_62_dialog_content = "When I saw how stoked you were to rebuild the valley...",
  ui_story_5058_50581202_63_dialog_content = "Well, I truly thought maybe I could finally forget all about the past and start over, but I was wrong.",
  ui_story_5058_50581202_64_dialog_content = "The Denuo Goddess came back.",
  ui_story_5058_50581202_65_dialog_content = "Came back for <color=#FFB400>revenge</color>.",
  ui_story_5058_50581301_1_dialog_content = "In this valley once sat a self-sufficient little village.",
  ui_story_5058_50581301_2_dialog_content = "For generations, the villagers believed the <color=#FFB400>Denuo Goddess</color> is their patron deity, protecting the canyon from Eclipsites.",
  ui_story_5058_50581301_3_dialog_content = "It was said people who saw the Goddess will receive her blessings and protection.",
  ui_story_5058_50581301_4_dialog_content = "However, no one could be sure the Goddess was real. Eventually, some villagers scoffed at the idea.",
  ui_story_5058_50581301_5_dialog_content = "Many more started to disregard the Goddess' warning in the story and poach the valley's resources, beginning with minerals, then plants, then even...",
  ui_story_5058_50581301_6_dialog_content = "Did you save a Denuo Goddess?",
  ui_story_5058_50581301_7_dialog_content = "Was it as pretty as a diamond like in the stories? Where did you see it?",
  ui_story_5058_50581301_8_dialog_content = "How do you ask, Dad?",
  ui_story_5058_50581301_9_dialog_content = "If the Denuo Goddess is real, we gotta take advantage of it, of course.",
  ui_story_5058_50581301_10_dialog_content = "No way, the Goddess is our patron deity!",
  ui_story_5058_50581301_11_dialog_content = "Why, you brat! How dare your lazy butt backtalk me! Do you think everything you got just fell out of the sky?",
  ui_story_5058_50581301_12_dialog_content = "I can care of myself just fine now, thank you!",
  ui_story_5058_50581301_13_dialog_content = "Fine, get out of my sight!",
  ui_story_5058_50581301_14_dialog_content = "I left home and was taken in by Coco, Lorelei's biological mother. But to my surprise, my father and others still discovered where the Goddess is hiding, subsequently finding a lot of baby butterflies...",
  ui_story_5058_50581301_15_dialog_content = "They wanted to make samples to sell to the rich in Umbraton and Lumopolis, only to accidentally discover the Goddess' powder could induce a comfortable coma.",
  ui_story_5058_50581301_16_dialog_content = "So they use it to make addictive incense.",
  ui_story_5058_50581301_17_dialog_content = "The Denuo Incense...",
  ui_story_5058_50581301_18_dialog_content = "Correct. The incense became an overnight sensation and best-seller throughout Astra.",
  ui_story_5058_50581301_19_dialog_content = "Although the production process required sacrificing the Denuo Goddess and excessive incense fume caused irreversible neuro damage, the villagers still hunted the butterflies as if they were possessed.",
  ui_story_5058_50581301_20_dialog_content = "Denuo boomed, and to prevent outsiders from stealing the formula, the villagers dug an underground tunnel.",
  ui_story_5058_50581301_21_dialog_content = "It's the passage in the back of the basement!",
  ui_story_5058_50581301_22_dialog_content = "The tunnel connected the village workshop to the heart of the valley in order to facilitate butterfly expeditions. But no one expected...",
  ui_story_5058_50581301_23_dialog_content = "Please, everyone, please leave the Denuo Goddess alone!",
  ui_story_5058_50581301_24_dialog_content = "There's never been one Eclipsite in the history of Denuo, but now...?",
  ui_story_5058_50581301_25_dialog_content = "We get swarms of them every day.",
  ui_story_5058_50581301_26_dialog_content = "It's a warning from the Denuo Goddess! We're taking so much from the valley that we're even eyeing our patron deity!",
  ui_story_5058_50581301_27_dialog_content = "Haha, hahaha!",
  ui_story_5058_50581301_28_dialog_content = "Someone still believe the Denuo Goddess is our patron deity? I'm laughing my face off.",
  ui_story_5058_50581301_29_dialog_content = "A word of advice, the butterfly can't protect the canyon since it can't even protect itself!",
  ui_story_5058_50581301_30_dialog_content = "The only good they do is the powder they release when they're scared.",
  ui_story_5058_50581301_31_dialog_content = "The Eclipsites are drawn here by the powerful Lumina in the powder.",
  ui_story_5058_50581301_32_dialog_content = "Don't be afraid. We already bought the most advanced weapons with the money we got. It's gonna be easy killing the Eclipsites.",
  ui_story_5058_50581301_33_dialog_content = "You should be thanking us for getting rid of Eclispites and keeping peace for someone who's out of touch with time like you!",
  ui_story_5058_50581301_34_dialog_content = "I don't need your protection...",
  ui_story_5058_50581301_35_dialog_content = "And please stop destroying the saplings I planted in the valley!",
  ui_story_5058_50581301_36_dialog_content = "Wait, did she say she planted trees? What a joke...",
  ui_story_5058_50581301_37_dialog_content = "I only remember how hard my mom worked just to make a living.",
  ui_story_5058_50581301_38_dialog_content = "I never knew she was planting trees for the gradually barren canyon even back then!",
  ui_story_5058_50581301_39_dialog_content = "But if Coco only knew that dozen of years later, her daughter Lorelei brought life back to the valley, she would be proud and ecstatic.",
  ui_story_5058_50581301_40_dialog_content = "A shame the villagers thought she was fool for not grabbing the money at the time...",
  ui_story_5058_50581301_41_dialog_content = "They didn't know a furious Goddess was about to rain doom down on Denuo.",
  ui_story_5058_50581301_42_dialog_content = "That day, I sneaked into where the villagers kept the Denuo Goddess only to see all the butterflies were gone...",
  ui_story_5058_50581301_43_dialog_content = "The baby butterflies they kept were all gone, Coco...",
  ui_story_5058_50581301_44_dialog_content = "Who in the village would do such a thing other than you and me?",
  ui_story_5058_50581301_45_dialog_content = "<color=#e8d9bb>Whoosh, whoosh...</color>",
  ui_story_5058_50581301_46_dialog_content = "This is weird. It usually isn't windy around this time...",
  ui_story_5058_50581301_47_dialog_content = "Do you see something in the wind too, Cena?",
  ui_story_5058_50581301_48_dialog_content = "Powder?",
  ui_story_5058_50581301_49_dialog_content = "?!",
  ui_story_5058_50581301_50_dialog_content = "It's the Denuo Goddess... She's mad from realizing her children have been murdered!",
  ui_story_5058_50581301_51_dialog_content = "This wind is not going to stop. We have to run for our lives, Cena, now!",
  ui_story_5058_50581301_52_dialog_content = "Oh no, Lorelei is still home...",
  ui_story_5058_50581301_53_dialog_content = "We went back to get Lorelei so we could leave the valley through a path marked with a smattering of vegetation.",
  ui_story_5058_50581301_54_dialog_content = "But on the way, I didn't notice a huge boulder teetering above...",
  ui_story_5058_50581301_55_dialog_content = "Coco shoved me out of the way only for herself to be crushed by the rock.",
  ui_story_5058_50581301_56_dialog_content = "Why did you save me? People like me aren't worth the effort...",
  ui_story_5058_50581301_57_dialog_content = "Foolish kid... Cough... I've always thought of you as family.",
  ui_story_5058_50581301_58_dialog_content = "Please hold on, Coco. I'll find something to move the boulder off you!",
  ui_story_5058_50581301_59_dialog_content = "I'm done for... Even if you move the boulder, cough... I still can't walk or leave.",
  ui_story_5058_50581301_60_dialog_content = "Thank you, Cena... for helping me all these years. Cough... I have one last favor to ask you...",
  ui_story_5058_50581301_61_dialog_content = "Run... Take Lorelei and... run...!",
  ui_story_5058_50581301_62_dialog_content = "Lorelei... Lorelei?!",
  ui_story_5058_50581301_63_dialog_content = "That was when I noticed the young Lorelei had been blown to the ground and passed out.",
  ui_story_5058_50581301_64_dialog_content = "I picked up Lorelei but before leaving, I turned to Coco only to see...",
  ui_story_5058_50581301_65_dialog_content = "The color slowly drains from her face under the heavy rock.",
  ui_story_5058_50581301_66_dialog_content = "Helplessness, remorse, guilt... So many emotions inundated me at once. I believed it was all a punishment from the Denuo Goddess to the villagers.",
  ui_story_5058_50581301_67_dialog_content = "And I was the one most deserving of punishment. If I hadn't found the young Goddess, none of this would've happened.",
  ui_story_5058_50581301_68_dialog_content = "Just when I was gonna give up and welcome my death in the sandstorm, I glanced at Lorelei and remembered Coco's dying wish.",
  ui_story_5058_50581301_69_dialog_content = "For Coco, for Lorelei, I must escape...",
  ui_story_5058_50581301_70_dialog_content = "The sandstorm completely destroyed Denuo. Almost no one survived other than me and Lorelei.",
  ui_story_5058_50581301_71_dialog_content = "But then you handed me to Shashona, my new mom.",
  ui_story_5058_50581301_72_dialog_content = "She was filthy rich, already. What's more, she really liked you, promised to heal you back to health and treat you like you're her own.",
  ui_story_5058_50581301_73_dialog_content = "That's a heck of a lot better than staying with a penniless bum like me.",
  ui_story_5058_50581301_74_dialog_content = "Not to mention she kept her word.",
  ui_story_5058_50581301_75_dialog_content = "So who freed the baby butterflies on the day of that sandstorm?",
  ui_story_5058_50581301_76_dialog_content = "Their mother. Who else could it be?",
  ui_story_5058_50581301_77_dialog_content = "The Denuo Goddess freed her children before punishing the village!",
  ui_story_5058_50581301_78_dialog_content = "So, not only did she not protect the people, but turned around and punished them?",
  ui_story_5058_50581301_79_dialog_content = "Why didn't you tell me that from the start?",
  ui_story_5058_50581301_80_dialog_content = "You were still too young, then. Coco didn't want you to know, either.",
  ui_story_5058_50581301_81_dialog_content = "What about now? You knew the truth yet agreed to use the Goddess as a gimmick to promote the park!",
  ui_story_5058_50581301_82_dialog_content = "Why would you even let us go find the butterfly in the valley?",
  ui_story_5058_50581301_83_dialog_content = "Why would you tell me you would make the Denuo Incense that the Board wanted?",
  ui_story_5058_50581301_84_dialog_content = "Are you trying to repeat that tragedy again?",
  ui_story_5058_50581301_85_dialog_content = "Or are you actually looking forward to the so-called punishment from the Goddess and planned everything?",
  ui_story_5058_50581301_86_dialog_content = "Well, how should I answer all that?",
  ui_story_5058_50581301_87_dialog_content = "Maybe yes, maybe not...",
  ui_story_5058_50581301_88_dialog_content = "Since I gave you to Ms. Shashona, I've been wandering Astra...",
  ui_story_5058_50581301_X88_dialog_content = "After all I've been through, I still couldn't get the sandstorm out of my head.",
  ui_story_5058_50581301_89_dialog_content = "Maybe I should've died then and there, not living like a coward.",
  ui_story_5058_50581301_90_dialog_content = "So...|I went back.",
  ui_story_5058_50581301_X90_dialog_content = "Although more than ten years had passed, I'd finally summoned up the courage to return and face the Denuo Goddess's judgment.",
  ui_story_5058_50581301_91_dialog_content = "But when I arrived, I discovered that Denuo Valley had already become a desert, and the Denuo Goddess was nowhere to be found.",
  ui_story_5058_50581301_92_dialog_content = "Just as I was thinking of ending it all, I discovered that someone had actually started rebuilding Denuo Valley!",
  ui_story_5058_50581301_93_dialog_content = "At that point, I didn't know a thing. I just didn't wanna see the only home I'd ever known become a wasteland.",
  ui_story_5058_50581301_94_dialog_content = "It was in that instant that I saw Coco, living on through you. I know that if she'd been there, she would've done exactly the same thing...",
  ui_story_5058_50581301_95_dialog_content = "Denuo Village had already been punished for forsaking its faith, and the valley was lain to waste as a result.",
  ui_story_5058_50581301_96_dialog_content = "But seeing as how the Denuo Goddess seemed to have vanished from the valley, could her punishment already run its course?",
  ui_story_5058_50581301_97_dialog_content = "Maybe... Maybe after rebuilding the valley, everything will go back to the way it was before—back to before the Denuo Goddess had been scorned.",
  ui_story_5058_50581301_98_dialog_content = "So, I made my choice. I chose to live... to help you restore the valley to its former glory...",
  ui_story_5058_50581301_99_dialog_content = "I wanted to witness the valley's glorious rebirth with my own eyes!",
  ui_story_5058_50581301_100_dialog_content = "You're forgetting about the underground passage...",
  ui_story_5058_50581301_101_dialog_content = "I thought every last trace of Denuo Village had been swept away in the sandstorm.",
  ui_story_5058_50581301_102_dialog_content = "Years later, I found out that the tunnel the villagers had used to catch the Denuo Goddess was still intact.",
  ui_story_5058_50581301_103_dialog_content = "I found myself faced with a dilemma. I considered setting the entire cavern ablaze and burying it forever...",
  ui_story_5058_50581301_104_dialog_content = "But Denuo Village is my home. How could I bring myself to destroy the last vestige of my people?",
  ui_story_5058_50581301_105_dialog_content = "I think that perhaps, one day, I'll leave the truth about what happened to the village in your hands, Lorelei. You can decide for yourself what happens to the ruins down there.",
  ui_story_5058_50581301_106_dialog_content = "I just never expected this day to come so soon! I guess I didn't think the Denuo Goddess would still harbor such an enduring grudge against the villagers...",
  ui_story_5058_50581301_107_dialog_content = "She's returned to claim vengeance! Back to punish me, the sinner who escaped a cruel death beneath the sands!",
  ui_story_5058_50581301_108_dialog_content = "Enough! Cena, you're taking this all too seriously.",
  ui_story_5058_50581301_109_dialog_content = "Revenge, sin... These wild ideas are all just products of an overactive mind.",
  ui_story_5058_50581301_110_dialog_content = "Even if the Denuo Goddesses do possess some mystical power, it's not the kind that can cause a sandstorm capable of destroying an entire village.",
  ui_story_5058_50581301_111_dialog_content = "Maybe it's not some kind of divine punishment, but more like the villagers of Denuo reaping what they sowed.",
  ui_story_5058_50581301_112_dialog_content = "The animals and plants of the valley created a sanctuary for the inhabitants of this barren land, but when that balance was broken, it was only natural that their shelter should disappear.",
  ui_story_5058_50581301_113_dialog_content = "Lorelei, whether you believe it or not... I've made up my mind to go find the Denuo Goddess and finally accept the punishment that's owed me.",
  ui_story_5058_50581301_114_dialog_content = "If what you're saying is true... shouldn't I have to accept some kind of punishment? I mean, I was part of Denuo Village back then too.",
  ui_story_5058_50581301_115_dialog_content = "You had nothing to do with all that. You were just a kid back then, you didn't even know what was going on.",
  ui_story_5058_50581301_116_dialog_content = "And... And I promised Coco I'd make sure you live a long and happy life!",
  ui_story_5058_50581301_117_dialog_content = "Happy? How can I be happy when my mom's in a coma!",
  ui_story_5058_50581301_118_dialog_content = "I hadn't anticipated something so serious happening to Shashona, but it's true that some have been known to fall into a persistent vegetative state after inhaling excessive amounts of Denuo Incense.",
  ui_story_5058_50581301_119_dialog_content = "What?!",
  ui_story_5058_50581301_120_dialog_content = "But I remember... there's an antidote that can neutralize the poison in the Denuo Goddess's scales, though it is rather hard to come by.",
  ui_story_5058_50581301_121_dialog_content = "I don't care how hard it is! Please, just tell me how to get it!",
  ui_story_5058_50581301_122_dialog_content = "Well, it's a kind of mucus.",
  ui_story_5058_50581301_123_dialog_content = "To be precise, it's the mucus the Denuo Goddess produces when producing eggs.",
  ui_story_5058_50581401_1_dialog_content = "<color=#e8d9bb>*Crowd murmuring*</color>",
  ui_story_5058_50581401_2_dialog_content = "What's going on? It sounds like we've got disgruntled customers on our hands...",
  ui_story_5058_50581401_3_dialog_content = "Boss, it's the staff...",
  ui_story_5058_50581401_4_dialog_content = "Everyone heard the story just now about the Denuo Goddess coming to get her revenge, and they're all terrified. A whole bunch of them wanna quit and get the heck out of here!",
  ui_story_5058_50581401_5_dialog_content = "Oh...",
  ui_story_5058_50581401_6_dialog_content = "Boss, this whole situation needs to be cleared up right away... How about we close the resort for a while, you know, for the safety of the staff and the guests...?",
  ui_story_5058_50581401_7_dialog_content = "Shut down the resort and let us go, boss!",
  ui_story_5058_50581401_8_dialog_content = "We shouldn't suffer the Denuo Goddess' wrath!",
  ui_story_5058_50581401_9_dialog_content = "Everyone, please just calm down for a moment.",
  ui_story_5058_50581401_10_dialog_content = "Call it quits, boss!",
  ui_story_5058_50581401_11_dialog_content = "Let us go home! Let us leave!",
  ui_story_5058_50581401_12_dialog_content = "My own employees... don't even trust me anymore.",
  ui_story_5058_50581401_13_dialog_content = "They're all just gonna turn their backs on me?",
  ui_story_5058_50581401_14_dialog_content = "I finally made it this far, but I never thought something like this would happen... and it's all because of my own carelessness...",
  ui_story_5058_50581401_15_dialog_content = "Perhaps I should've listened to Mom from the very start instead of trying so hard to prove myself...",
  ui_story_5058_50581401_16_dialog_content = "It's all my fault... I don't have what it takes to make a business like this work yet...",
  ui_story_5058_50581401_17_dialog_content = "You can't think like that, Lorelei!",
  ui_story_5058_50581401_18_dialog_content = "Yes, Lorelei! This kind of defeatist talk isn't like you at all.",
  ui_story_5058_50581401_19_dialog_content = "Just think about how you managed to rebuild the valley and set up such a luxurious resort here... Obviously, you're a natural at this sort of thing!",
  ui_story_5058_50581401_20_dialog_content = "I totally agree, I don't think you need to prove yourself to anyone!",
  ui_story_5058_50581401_21_dialog_content = "But Mom has never had anything nice to say about me, and now she's in a coma, and it's all my fault...",
  ui_story_5058_50581401_22_dialog_content = "I'm sure Shashona knows how great you are.",
  ui_story_5058_50581401_23_dialog_content = "From the moment I met her, I could tell just how proud she was of your resort!",
  ui_story_5058_50581401_24_dialog_content = "But Mom... she never said a good word about the resort to me.",
  ui_story_5058_50581401_25_dialog_content = "Oh, I never would've guessed, either... So, it turns out that the shrewd Ms. Shashona was trying her best to hide her true feelings from her daughter.",
  ui_story_5058_50581401_26_dialog_content = "It seems she simply wasn't ready to—",
  ui_story_5058_50581401_27_dialog_content = "No! Lorelei...",
  ui_story_5058_50581401_28_dialog_content = "Mom?",
  ui_story_5058_50581401_29_dialog_content = "Don't leave me...",
  ui_story_5058_50581401_30_dialog_content = "I never planned on leaving you, Mom... Do you hear me?",
  ui_story_5058_50581401_31_dialog_content = "...",
  ui_story_5058_50581401_32_dialog_content = "So, this is what you've been afraid of all this time?",
  ui_story_5058_50581401_33_dialog_content = "Mom...",
  ui_story_5058_50581401_34_dialog_content = "Boss, the staff... They're all still waiting for an answer...",
  ui_story_5058_50581401_35_dialog_content = "I understand.",
  ui_story_5058_50581401_36_dialog_content = "Mom, I won't back down now.",
  ui_story_5058_50581401_37_dialog_content = "I didn't get to where I am today for anyone but myself... I have my own dream.",
  ui_story_5058_50581401_38_dialog_content = "I chose to follow the hardest path before me to make this dream come true, and I realized something a long time ago.",
  ui_story_5058_50581401_39_dialog_content = "No matter what hardships come my way, I have to have face them head-on!",
  ui_story_5058_50581401_40_dialog_content = "Not as a daughter, not as a naive entrepreneur, not as a profiteering opportunist...",
  ui_story_5058_50581401_41_dialog_content = "But as a boss with employees to lead and customers to serve! A boss who bravely faces and solves her problems!",
  ui_story_5058_50581401_42_dialog_content = "It looks like the Lorelei we know and love is back!",
  ui_story_5058_50581401_43_dialog_content = "Thank you, PlayerName...",
  ui_story_5058_50581401_44_dialog_content = "Denuo Valley Resort employees! Listen up!",
  ui_story_5058_50581401_45_dialog_content = "I know you're all feeling afraid right now, and you must have a lot of questions. I failed to conduct a thorough preliminary investigation of the area, and I apologize for this.",
  ui_story_5058_50581401_46_dialog_content = "So, first, I just wanna say... I'm so sorry, everyone!",
  ui_story_5058_50581401_47_dialog_content = "Making this resort a success... Well, it's my dream.",
  ui_story_5058_50581401_48_dialog_content = "It's taken so much blood, sweat, and tears for us to transform this valley together.",
  ui_story_5058_50581401_49_dialog_content = "And because of this, the Denuo Valley Resort is no longer simply my dream.",
  ui_story_5058_50581401_50_dialog_content = "Every brick of this place, every tile, bears the immortal mark of everyone's hard work. This is our shared dream—this is our home!",
  ui_story_5058_50581401_51_dialog_content = "So, we've come up against our first hurdle. I don't wanna shut down the resort and instantly give up just because of this...",
  ui_story_5058_50581401_52_dialog_content = "I can't turn my back on our dream, I won't abandon the home we worked so hard to build!",
  ui_story_5058_50581401_53_dialog_content = "I know you're all scared, I know you're anxious, and to be honest, this is the first time I've ever come up against a problem like this.",
  ui_story_5058_50581401_54_dialog_content = "But I want you all to know that I'm taking charge of the situation, and I promise I'll resolve this matter as quickly as I can.",
  ui_story_5058_50581401_55_dialog_content = "Although the future may be uncertain, please, just give me a little more time... I promise I'll make this right!",
  ui_story_5058_50581401_56_dialog_content = "...",
  ui_story_5058_50581401_57_dialog_content = "Since the boss put it that way...",
  ui_story_5058_50581401_58_dialog_content = "I do want my family to visit the resort!",
  ui_story_5058_50581401_59_dialog_content = "And I want my friends to see the awesome place I work for...",
  ui_story_5058_50581401_60_dialog_content = "I also hope that you can find the strength to return to your stations and continue serving our current customers to the best of your ability.",
  ui_story_5058_50581401_61_dialog_content = "I need to know you all have my back! Please, give me the courage to go on and take care of all this!",
  ui_story_5058_50581401_62_dialog_content = "I believe that as long as we work together, we'll definitely overcome this minor setback and get the resort back on track!",
  ui_story_5058_50581401_63_dialog_content = "I believe in each and every one of you... Will you believe in me?",
  ui_story_5058_50581401_64_dialog_content = "...",
  ui_story_5058_50581401_65_dialog_content = "Boss, I... I believe in you!",
  ui_story_5058_50581401_66_dialog_content = "We trust you, Lorelei!",
  ui_story_5058_50581401_67_dialog_content = "Trust you, trust you, trust you!",
  ui_story_5058_50581401_68_dialog_content = "Lorelei... seems more mature than before, don't you think?",
  ui_story_5058_50581401_69_dialog_content = "I think she's always been a pretty mature businesswoman, but now she's got a little more strength and conviction than she used to.",
  ui_story_5058_50581401_70_dialog_content = "PlayerName, what are you two muttering about?",
  ui_story_5058_50581401_71_dialog_content = "He was just singing your praises, Lorelei!",
  ui_story_5058_50581401_72_dialog_content = "Huh?",
  ui_story_5058_50581401_73_dialog_content = "Thanks, PlayerName... Thanks everyone...",
  ui_story_5058_50581401_74_dialog_content = "But now I need you all to lend me a hand.",
  ui_story_5058_50581401_75_dialog_content = "Alright, we'll take care of the leftover Eclipsites around here.",
  ui_story_5058_50581401_76_dialog_content = "And I'd also like to get to the bottom of all this.",
  ui_story_5058_50581401_77_dialog_content = "You mean...",
  ui_story_5058_50581401_78_dialog_content = "I need to go deep into the valley and find the Denuo Goddess, find out what she wants, and... find an antidote for my mom.",
  ui_story_5058_50581401_79_dialog_content = "It looks like we're heading the same way, then.",
  ui_story_5058_50581401_80_dialog_content = "Come with me. Just be careful—that scale dust seems to attract Eclipsites.",
  ui_story_5058_50581401_81_dialog_content = "Also, cover your nose and mouth with a damp cloth so you don't collapse before we even get there.",
  ui_story_5058_50581501_1_dialog_content = "Rapid Torrent!",
  ui_story_5058_50581501_2_dialog_content = "Ugh...",
  ui_story_5058_50581501_3_dialog_content = "There're so many Eclipsites around here!",
  ui_story_5058_50581501_4_dialog_content = "Why isn't the scale dust affecting the Eclipsites?",
  ui_story_5058_50581501_5_dialog_content = "I'm guessing it's because their physiology is different from us, though they're attracted and get excited by the Lumina in the powder.",
  ui_story_5058_50581501_6_dialog_content = "It's clear where the highest concentrations of scale dust are—that's where you'll find the largest clusters of Eclipsites...",
  ui_story_5058_50581501_7_dialog_content = "Roar!",
  ui_story_5058_50581501_8_dialog_content = "Outta my way!",
  ui_story_5058_50581501_9_dialog_content = "It feels like the further we go, the more scale dust there is. Does that mean we're getting closer to the Denuo Goddess?",
  ui_story_5058_50581501_10_dialog_content = "Wait, I sense something bursting with Lumina charging toward us...",
  ui_story_5058_50581501_11_dialog_content = "Maybe it's an Aurorian coming to lend us a hand?",
  ui_story_5058_50581501_12_dialog_content = "But I didn't ask anyone else to come help us.",
  ui_story_5058_50581501_13_dialog_content = "Well, I guess that leaves only one possibility...",
  ui_story_5058_50581501_14_dialog_content = "It's here!",
  ui_story_5058_50581501_15_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581501_16_dialog_content = "<size=45>Hiss!</size>",
  ui_story_5058_50581501_17_dialog_content = "Huh? I-It's...!",
  ui_story_5058_50581501_18_dialog_content = "It's the Denuo Goddess...",
  ui_story_5058_50581501_19_dialog_content = "!!!",
  ui_story_5058_50581501_20_dialog_content = "But this thing is completely different from that cute little Denuo Goddess sticker!",
  ui_story_5058_50581501_21_dialog_content = "That sticker shows you what these things look like when they're just hatched. This Denuo Goddess floating in front of us right now is a fully-grown <color=#FFB400>butterfly queen</color>, ready to lay her own eggs...",
  ui_story_5058_50581501_22_dialog_content = "<size=45>Hiss, hiss, hiss!</size>",
  ui_story_5058_50581501_23_dialog_content = "<color=#e8d9bb>Whoosh—Whoosh—</color>",
  ui_story_5058_50581501_24_dialog_content = "Everyone, find a plant to hide behind so you don't get blown away by the Denuo Goddess's flapping wings!",
  ui_story_5058_50581501_25_dialog_content = "Denuo Goddess, the legends say you possess unmatched wisdom, so surely you can understand what I'm saying to you right now, correct?",
  ui_story_5058_50581501_26_dialog_content = "<size=45>Hiss!</size>",
  ui_story_5058_50581501_27_dialog_content = "Watch out, Lorelei!",
  ui_story_5058_50581501_28_dialog_content = "Ugh...",
  ui_story_5058_50581501_29_dialog_content = "Cena?!",
  ui_story_5058_50581501_30_dialog_content = "Can you remember anyone mentioning the Denuo Goddess was still this strong?",
  ui_story_5058_50581501_31_dialog_content = "I don't think so.",
  ui_story_5058_50581501_32_dialog_content = "Cough, cough... It appears the Denuo Goddess's wrath won't be so easy to appease...",
  ui_story_5058_50581501_33_dialog_content = "Get out of here, quickly. Let me handle this myself.",
  ui_story_5058_50581501_34_dialog_content = "What the heck are you talking about!",
  ui_story_5058_50581501_35_dialog_content = "<size=45>Hiss, hiss, hiss!</size>",
  ui_story_5058_50581502_1_dialog_content = "Denuo Goddess, this is all a big misunderstanding!",
  ui_story_5058_50581502_2_dialog_content = "We don't wish to harm you... We couldn't if we wanted to!",
  ui_story_5058_50581502_3_dialog_content = "<size=45>Hiss, hiss, hiss!</size>",
  ui_story_5058_50581502_4_dialog_content = "My mom's in a coma... She breathed in too much of your scale dust, and you're the only one who can—",
  ui_story_5058_50581502_5_dialog_content = "It's no use...",
  ui_story_5058_50581502_6_dialog_content = "Why? Cena, can't you communicate with insects? Do you know what the Denuo Goddess is saying?",
  ui_story_5058_50581502_7_dialog_content = "The Denuo Goddess... she's just saying \"never forgive, never forgive, never forgive\" over and over again...",
  ui_story_5058_50581502_8_dialog_content = "!!!",
  ui_story_5058_50581502_9_dialog_content = "Now you all know, she's back for revenge!",
  ui_story_5058_50581502_10_dialog_content = "<size=45>Hiss, hiss, hiss!</size>",
  ui_story_5058_50581502_11_dialog_content = "Ugh...",
  ui_story_5058_50581502_12_dialog_content = "Lorelei!!!",
  ui_story_5058_50581502_13_dialog_content = "Are you okay, Lorelei?!",
  ui_story_5058_50581502_14_dialog_content = "Cough, cough... I... I'm still holding on...",
  ui_story_5058_50581502_15_dialog_content = "If we're forced to exert ourselves like this for much longer, I'm afraid things could take a turn for the worse.",
  ui_story_5058_50581502_16_dialog_content = "Come on, Lorelei! Let me help you to your feet!",
  ui_story_5058_50581502_17_dialog_content = "Hey... What's that about to drop from this tree?",
  ui_story_5058_50581502_18_dialog_content = "Denuo Goddess, if you wanna punish someone, punish me, and me alone!",
  ui_story_5058_50581502_19_dialog_content = "Over ten years ago, I happened to save a Denuo Goddess by chance and was careless enough to let the whole village find out about it...",
  ui_story_5058_50581502_20_dialog_content = "Hiss...?",
  ui_story_5058_50581502_21_dialog_content = "That's right, it was me... If it weren't for my actions, the people of Denuo Village would never have wantonly captured the Denuo Goddess...",
  ui_story_5058_50581502_22_dialog_content = "I'm the one who should've faced divine punishment in that sandstorm! But I ran away instead...",
  ui_story_5058_50581502_23_dialog_content = "I had to run away! Someone very important to me gave me a mission, and I had to complete it!",
  ui_story_5058_50581502_24_dialog_content = "I ran away over ten years ago, and my soul has been tormented ever since. I stand here before you seeking redemption!",
  ui_story_5058_50581502_25_dialog_content = "But please let me bear the sins of the past alone.",
  ui_story_5058_50581502_26_dialog_content = "This has nothing to do with Lorelei and those other youngsters back there, or the guests back at the resort...",
  ui_story_5058_50581502_27_dialog_content = "I'm willing to give my life to make this right!",
  ui_story_5058_50581502_28_dialog_content = "Please, just give them the antidote for the scale dust's poison and let them go...",
  ui_story_5058_50581502_29_dialog_content = "(Does it seem like... the Denuo Goddess has... calmed down?)",
  ui_story_5058_50581502_30_dialog_content = "Denuo Goddess, please... grant me the most painful end you can upon your deadly wings...",
  ui_story_5058_50581502_31_dialog_content = "Maybe, I should just end my life before your eyes with my own weapon...",
  ui_story_5058_50581502_32_dialog_content = "What are you doing, Cena?!",
  ui_story_5058_50581502_33_dialog_content = "I realized when we met up again back then how you're always trying to present yourself as this mature guy who knows so much about the world!",
  ui_story_5058_50581502_34_dialog_content = "The truth is, you haven't grown up at all! All you ever do is avoid your problems instead of trying to overcome them!",
  ui_story_5058_50581502_35_dialog_content = "Is the only thing you're living for really just redemption? You didn't even do anything wrong back then!",
  ui_story_5058_50581502_36_dialog_content = "Mom... Coco saved you back then, and Shashona saved you too.",
  ui_story_5058_50581502_37_dialog_content = "And the reason they did it is because they thought you were worth saving! But just look at you! Why do you insist on trying to throw away your life like this?",
  ui_story_5058_50581502_38_dialog_content = "You want people to say my moms were both fools who gave their lives in vain?!",
  ui_story_5058_50581502_39_dialog_content = "No... That's not...",
  ui_story_5058_50581502_40_dialog_content = "Denuo Goddess, please listen to me. All I want to do is clear up this misunderstanding between us!",
  ui_story_5058_50581502_41_dialog_content = "Hiss?",
  ui_story_5058_50581502_42_dialog_content = "Coco told me that you grant blessings and protection to those you meet...",
  ui_story_5058_50581502_43_dialog_content = "I believe what she told me, and I also believe that you'd never be so cruel as to hand down such a twisted form of so-called divine punishment.",
  ui_story_5058_50581502_44_dialog_content = "I came back to Denuo Valley to breathe life back into this place! I won't make the same mistakes the villagers did back then!",
  ui_story_5058_50581502_45_dialog_content = "I'm glad you've returned to Denuo Valley too, because this means all I've done to restore the valley hasn't been in vain...",
  ui_story_5058_50581502_46_dialog_content = "You fact that you'd lay your eggs in the valley again is proof enough that I've made a difference!",
  ui_story_5058_50581502_47_dialog_content = "Hiss, hiss, hiss!",
  ui_story_5058_50581502_48_dialog_content = "Denuo Goddess! I mean your young no harm!",
  ui_story_5058_50581502_49_dialog_content = "I picked this up just now not knowing what it was... Here, let me return it to you!",
  ui_story_5058_50581502_50_dialog_content = "I understand... You thought we wanted to hurt your child, and that's why you got so angry. Am I right?",
  ui_story_5058_50581502_51_dialog_content = "Hiss, hiss, hiss, hiss!",
  ui_story_5058_50581502_52_dialog_content = "She saw... that we were carrying nets and trying to catch her children.",
  ui_story_5058_50581502_53_dialog_content = "This is all my fault! Although I was born in Denuo Valley, I hardly know anything about you...",
  ui_story_5058_50581502_54_dialog_content = "I brought everyone here to the valley... In fact, I had hoped that I could perhaps find a way to help the Denuo Goddesses flourish here once again...",
  ui_story_5058_50581502_55_dialog_content = "It's only now that I understand how naive and arrogant it was for me to think that.",
  ui_story_5058_50581502_56_dialog_content = "This valley is my home, and the resort is a dream many of us hold dear... That's why I promise to protect this place more passionately than anyone!",
  ui_story_5058_50581502_57_dialog_content = "I implore you—please trust me! I know I can find a way to protect your natural habitat and keep your young from being disturbed!",
  ui_story_5058_50581502_58_dialog_content = "Hiss?",
  ui_story_5058_50581502_59_dialog_content = "You want to ask me something?",
  ui_story_5058_50581502_60_dialog_content = "Yes, I think she's worth trusting. Her mother, Coco, also wanted to protect Denuo Valley and its butterflies once upon a time!",
  ui_story_5058_50581502_61_dialog_content = "I believe she has inherited Coco's ideals... That's why I believe in her!",
  ui_story_5058_50581502_62_dialog_content = "Hiss, hiss...",
  ui_story_5058_50581502_63_dialog_content = "The Denuo Goddess doesn't seem all that angry anymore!",
  ui_story_5058_50581502_64_dialog_content = "<color=#e8d9bb>Crack!</color>",
  ui_story_5058_50581502_65_dialog_content = "Hiss...",
  ui_story_5058_50581502_66_dialog_content = "Huh? Your child is about to emerge from its cocoon?! Wh-What should we do...? I'm still holding it in my hands!",
  ui_story_5058_50581502_67_dialog_content = "<color=#e8d9bb>The Denuo Goddess took the glowing cocoon from Lorelei's hand.</color>",
  ui_story_5058_50581502_68_dialog_content = "You can come out now...",
  ui_story_5058_50581502_69_dialog_content = "Mom...",
  ui_story_5058_50581502_70_dialog_content = "Well done, my child. You've grown bigger.",
  ui_story_5058_50581502_71_dialog_content = "I grew! I want to be as big as you, Mom!",
  ui_story_5058_50581502_72_dialog_content = "Oh, and...",
  ui_story_5058_50581502_73_dialog_content = "I trust this young lady! If it wasn't for her, I would have fellen from the tree and never seen Mom again!",
  ui_story_5058_50581502_74_dialog_content = "The little butterfly... landed on Lorelei?!",
  ui_story_5058_50581502_75_dialog_content = "...",
  ui_story_5058_50581502_76_dialog_content = "Then we must give her our sincerest gratitude.",
  ui_story_5058_50581502_77_dialog_content = "You want me to... reach out my hand?",
  ui_story_5058_50581502_78_dialog_content = "Huh? Is this the cocoon that little butterfly popped out of just now?",
  ui_story_5058_50581502_79_dialog_content = "I apologize for incapacitating your mom. The fluid inside the cocoon is the antidote.",
  ui_story_5058_50581502_80_dialog_content = "We will relocate deeper into the valley. I believe you will adhere to your promise.",
  ui_story_5058_50581502_81_dialog_content = "Is this... the mucus Cena was talking about? Thank you, Denuo Goddess! Thank you!",
  ui_story_5058_50581502_82_dialog_content = "I promise I'll keep my word!",
  ui_story_5058_50581502_83_dialog_content = "Good luck.",
  ui_story_5058_50581502_84_dialog_content = "Lorelei... You received the Denuo Goddess's blessing?!",
  ui_story_5058_50581502_85_dialog_content = "You...",
  ui_story_5058_50581502_86_dialog_content = "Oh... Denuo Goddess, Cena's been protecting the valley with me this whole time! He's not as bad as he says he is...",
  ui_story_5058_50581502_87_dialog_content = "Please don't—",
  ui_story_5058_50581502_88_dialog_content = "Huh?",
  ui_story_5058_50581502_89_dialog_content = "<color=#e8d9bb>The Denuo Goddess touched the transparent wings on Cena's back.</color>",
  ui_story_5058_50581502_90_dialog_content = "Hiss... I look different now and so do you, but I still remember those wings.",
  ui_story_5058_50581502_91_dialog_content = "What a beautiful pair of wings it is.",
  ui_story_5058_50581502_92_dialog_content = "Thank you for freeing me from the cobweb before.",
  ui_story_5058_50581502_93_dialog_content = "It... It was you?",
  ui_story_5058_50581502_94_dialog_content = "That sandstorm from a dozen years ago had nothing to do with us, and I am sorry for your suffering.",
  ui_story_5058_50581502_95_dialog_content = "I have always been looking for you, not to punish you but to thank you.",
  ui_story_5058_50581502_96_dialog_content = "Thank you for giving me another life, and may you find the purpose of yours.",
  ui_story_5058_50581502_97_dialog_content = "I-I will...",
  ui_story_5058_50581502_98_dialog_content = "I look very much forward to seeing your child with wings as specular as yours.",
  ui_story_5058_50581502_99_dialog_content = "Apart from Luke, no one has ever appreciated my wings like that...",
  ui_story_5058_50581502_100_dialog_content = "It is time for us to go, my child.",
  ui_story_5058_50581502_101_dialog_content = "Wait for me, Mom!",
  ui_story_5058_50581502_102_dialog_content = "It left, just like that?",
  ui_story_5058_50581502_103_dialog_content = "Huh? All the Eclipsites around here have cleared off too?!",
  ui_story_5058_50581502_104_dialog_content = "So... is it all over now? Everything happened so suddenly, I haven't even had a chance to process it all...",
  ui_story_5058_50581502_105_dialog_content = "Haha... Hahahahaha!",
  ui_story_5058_50581502_106_dialog_content = "What's the big idea, Cena?! Don't just start laughing like that all of a sudden, you're creeping me out...",
  ui_story_5058_50581502_107_dialog_content = "I just had to laugh at myself. Even though I clearly have these wings on my back, I still couldn't figure out what the Denuo Goddess was thinking, after all this time.",
  ui_story_5058_50581502_108_dialog_content = "Whether you're a Denuo Goddess, an average insect, or a demi-human like me, we're all very simple at heart.",
  ui_story_5058_50581502_109_dialog_content = "And as long as you don't harm them, they'll never attack unprovoked.",
  ui_story_5058_50581502_110_dialog_content = "They can forget a thousand grudges overnight, but will remember a single act of kindness for a lifetime.",
  ui_story_5058_50581502_111_dialog_content = "They can even forget their grudges?",
  ui_story_5058_50581502_112_dialog_content = "Cena, what did the Denuo Goddess say to you before she left?",
  ui_story_5058_50581502_113_dialog_content = "She blessed me with...",
  ui_story_5058_50581502_114_dialog_content = "The courage to go on living.",
  ui_story_5058_50581601_1_dialog_content = "What did you say?!",
  ui_story_5058_50581601_2_dialog_content = "Remove all hype related to the Denuo Goddess?",
  ui_story_5058_50581601_3_dialog_content = "As valued investors, this is the first matter I wanted to bring to your attention today.",
  ui_story_5058_50581601_4_dialog_content = "The second matter I'd like to inform you of is that I won't be continuing the development of Denuo Incense, and thirdly, I can now confirm that the second phase of the resort's expansion plan has for all intents and purposes been canceled.",
  ui_story_5058_50581601_5_dialog_content = "Do you even know what you're saying?",
  ui_story_5058_50581601_6_dialog_content = "All three are the best way to ensure the resort will recoup investment money and keep operating! Can you run a business?",
  ui_story_5058_50581601_7_dialog_content = "Heh, don't worry about that right now! From the sounds of things... you've got some other plans up your sleeve, don'tcha boss?",
  ui_story_5058_50581601_8_dialog_content = "I know this might be difficult for you to accept at first, but after careful consideration, I've decided that the Denuo Valley Resort should operate under a more conscientious business philosophy.",
  ui_story_5058_50581601_9_dialog_content = "Whether it's marketing, services, or locally-sourced products, we need to keep the concept of valley sustainability in mind at all times, and follow a guiding principle of ecological development.",
  ui_story_5058_50581601_10_dialog_content = "The aforementioned activities might generate short-term profits, but they neglect to address the impact we're having on the environment and the consequences that'll arise sooner or later.",
  ui_story_5058_50581601_11_dialog_content = "This is why I propose we continue improving the environment within the valley and forge an ecosystem where Aurorians, animals, and plants can coexist...",
  ui_story_5058_50581601_12_dialog_content = "Keep improving the environment? All that just to get more money out of us?",
  ui_story_5058_50581601_13_dialog_content = "According to my calculations, the profit from the resort's basic operation, minus various expenses, should be sufficient to support my proposed plan!",
  ui_story_5058_50581601_14_dialog_content = "Do you take us for fools? You got so much from us already! Do you think this is a charity?",
  ui_story_5058_50581601_15_dialog_content = "I've carried out a range of preliminary tests, and I'm totally confident that the resort's new incarnation will be a surefire hit! All we need to do is open the gates and watch the guests flood in!",
  ui_story_5058_50581601_16_dialog_content = "First we need to try our best to establish a good reputation, secure profits for the current period, and continuously improve the environment in the valley...",
  ui_story_5058_50581601_17_dialog_content = "Once we're sure the valley's natural environment can be preserved completely, we can build a wildlife reserve for our guests to enjoy.",
  ui_story_5058_50581601_18_dialog_content = "Not only will this provide our guests with a unique and novel experience, it'll ensure that the resort offers an idyllic environment to everyone who visits.",
  ui_story_5058_50581601_19_dialog_content = "And with that, our resort will hold a solid competitive edge over all Astra!",
  ui_story_5058_50581601_20_dialog_content = "Needless to say, all this is guaranteed to rake in huge returns on your investments in the long run!",
  ui_story_5058_50581601_21_dialog_content = "Heheh... It's so good to see you laying down your own ideas and just running with them, Lorelei!",
  ui_story_5058_50581601_22_dialog_content = "I've always been one to encourage and support the entrepreneurial spirit when I see it!",
  ui_story_5058_50581601_23_dialog_content = "Even if my investment won't bring in any returns any time soon, that's fine by me... I don't mind waiting a couple more days for my money.",
  ui_story_5058_50581601_24_dialog_content = "I'll continue supervising your progress, of course, to make sure you stay on track and do what you set out to achieve. Otherwise, I might have to withdraw my support too.",
  ui_story_5058_50581601_25_dialog_content = "Ridiculous! What about the rest of you? I don't think you'll keep falling for this stupid project!",
  ui_story_5058_50581601_26_dialog_content = "Take it easy. I'm happy for her and her ideas.",
  ui_story_5058_50581601_27_dialog_content = "However... You know what you're doing now is clearly in violation of the contract we signed, right, Lorelei?",
  ui_story_5058_50581601_28_dialog_content = "According to the terms, you have to pay us triple for the breach.",
  ui_story_5058_50581601_29_dialog_content = "Sure, that's right. Can you afford it, Lorelei?",
  ui_story_5058_50581601_30_dialog_content = "I...",
  ui_story_5058_50581601_31_dialog_content = "J-Just three times more?! Ahhh... What am I supposed to tell Father now?!",
  ui_story_5058_50581601_32_dialog_content = "Rub salt in the wounds of a steadfast friend, and you're sure to meet a sticky end.",
  ui_story_5058_50581601_33_dialog_content = "If you told us this from the beginning, Lorelei, we would've never invested...",
  ui_story_5058_50581601_34_dialog_content = "Yes, me neither...",
  ui_story_5058_50581601_35_dialog_content = "Don't worry, Lorelei!",
  ui_story_5058_50581601_36_dialog_content = "Who do you all think you're looking down on? It's not like we can't afford it ourselves—",
  ui_story_5058_50581601_37_dialog_content = "...",
  ui_story_5058_50581601_38_dialog_content = "Ahem... I'm just one hundred percent confident that my daughter can handle this with one arm tied behind her back!",
  ui_story_5058_50581601_39_dialog_content = "(Mom...)",
  ui_story_5058_50581601_40_dialog_content = "I sincerely apologize to all of you, and I'm fully aware that my actions violated the terms of our original contract.",
  ui_story_5058_50581601_41_dialog_content = "I take full responsibility and won't try to pass the buck.",
  ui_story_5058_50581601_42_dialog_content = "But I also need you all to believe that my determination to rebuild the valley is as unfaltering as my determination to run an excellent resort!",
  ui_story_5058_50581601_43_dialog_content = "I'm fully confident that I can secure better returns on your investments. It's just that... you may need to wait a little longer than expected.",
  ui_story_5058_50581601_44_dialog_content = "I understand and applaud you.",
  ui_story_5058_50581601_45_dialog_content = "But I'll have my attorney send you a bill, Lorelei.",
  ui_story_5058_50581601_46_dialog_content = "Don't say we never gave you a chance... Start worrying about your bankruptcy.",
  ui_story_5058_50581601_47_dialog_content = "Laurie...",
  ui_story_5058_50581601_48_dialog_content = "Phew... It's fine, Mom. I thought things might turn out this way.",
  ui_story_5058_50581601_49_dialog_content = "But it's not over yet. I won't use the family fortune to make up the difference until I at least ask the guild for help first...",
  ui_story_5058_50581601_50_dialog_content = "Well, there's no point in trying to stop a die-hard rebel like you.",
  ui_story_5058_50581601_51_dialog_content = "Hah, you're not wrong... but I know I'm doing the right thing, and that's enough for me.",
  ui_story_5058_50581601_52_dialog_content = "I like the way you can't stand those old fogeys either.",
  ui_story_5058_50581601_53_dialog_content = "I know of a certain sucker who apparently has more than a few Nightium to spare, and a reasonably-sized entourage to boot.",
  ui_story_5058_50581601_54_dialog_content = "If she knew I'd invested here, I'm sure she'd be falling over herself to throw in even more funding than me.",
  ui_story_5058_50581601_55_dialog_content = "Please promise you'll introduce me to her!",
  ui_story_5058_50581601_56_dialog_content = "Her wings sparkled like a gem in the sunlight!",
  ui_story_5058_50581601_57_dialog_content = "Dang, I should've come along with you guys...",
  ui_story_5058_50581601_58_dialog_content = "Hmm, didn't you say it's better to have one less problem than one more headache, then go sleep like a log?",
  ui_story_5058_50581601_59_dialog_content = "Is it my fault the hotel bed's so soft and smells so gosh darn good? I've never kipped in such a comfy crib before...",
  ui_story_5058_50581601_60_dialog_content = "Never mind... Fia and I are working as senior animal experts for the resort, so we might still get the chance to meet the Denuo Goddess someday soon.",
  ui_story_5058_50581601_61_dialog_content = "Master, are you really planning on wasting your days here forever?",
  ui_story_5058_50581601_62_dialog_content = "PlayerName, what are you still doing hanging around here chatting for?",
  ui_story_5058_50581601_63_dialog_content = "Look, me and Carleen have saved up a bunch of stickers already!",
  ui_story_5058_50581601_64_dialog_content = "They've really shaken up their marketing campaign—even the butterflies on these stickers have been replaced...",
  ui_story_5058_50581601_65_dialog_content = "But the rules are the same as before—just save up enough stickers and you can trade them in for prizes!",
  ui_story_5058_50581601_66_dialog_content = "We heard that the grand prize is an annual pass for Denuo Valley Resort.",
  ui_story_5058_50581601_67_dialog_content = "If you don't save up enough stickers, PlayerName... I'll just take Carleen next time! I won't even bother asking you!",
  ui_story_5058_50581601_68_dialog_content = "You'd really go without me?",
  ui_story_5058_50581601_69_dialog_content = "Ahem... Look, if you don't wanna miss out, come play Fantasy Matrix with us!",
  ui_story_5058_50581601_70_dialog_content = "What? You're still messing with that thing?!",
  ui_story_5058_50581601_71_dialog_content = "Here's some free advice—next time, don't even think about letting Sinsa design a theme park attraction...",
  ui_story_5058_50581601_72_dialog_content = "Found it.",
  ui_story_5058_50581601_73_dialog_content = "Cena, haven't you done enough?",
  ui_story_5058_50581601_74_dialog_content = "Can you finally hang out with us today?",
  ui_story_5058_50581601_75_dialog_content = "Ladies, thank you all for the plethora of insightful comments and suggestions you've proposed to the resort!",
  ui_story_5058_50581601_76_dialog_content = "Acting on your wishes, Lorelei has asked me to speed up the adjustments to the resort's equipment and various services based on your suggestions.",
  ui_story_5058_50581601_77_dialog_content = "Something's different about Cena...",
  ui_story_5058_50581601_78_dialog_content = "Huh? Really? Haven't I ever shown you ladies my cool, competent side before?",
  ui_story_5058_50581601_79_dialog_content = "Have you met?",
  ui_story_5058_50581601_80_dialog_content = "No.",
  ui_story_5058_50581601_81_dialog_content = "Yikes... That was savage, Winona. Haha...",
  ui_story_5058_50581601_82_dialog_content = "Cena, don't get carried away chatting to the guests! Remember, we've got a lot of work to do!",
  ui_story_5058_50581601_83_dialog_content = "Oh, right... I'd almost forgotten...",
  ui_story_5058_50581601_84_dialog_content = "Ladies, I must take my leave! Please, don't miss me too much—we can reminisce about old times later!",
  ui_story_5058_50581601_85_dialog_content = "Should we keep waiting?",
  ui_story_5058_50581601_86_dialog_content = "Nah, he seemed fine enough for us to stop worrying.",
  ui_story_5058_50581601_87_dialog_content = "What a shame. How about we go see the Caelestite?",
  ui_story_5058_50581601_88_dialog_content = "Hey, that's not a bad idea.",
  ui_story_5058_50581601_89_dialog_content = "Hmm? I just went off for a minute to grab a lizard ice cream! Where did everyone go?",
  ui_story_5058_50581601_90_dialog_content = "<size=45>Did they forget about me again?!</size>",
  ui_story_5058_50581601_91_dialog_content = "The first time I took you on the sky wheel, you could barely see the view, even when standing up.",
  ui_story_5058_50581601_92_dialog_content = "I remember, I remember! I was really angry and started whining about how the sky wheel hadn't been designed properly, and that I wanted to complain to the manager.",
  ui_story_5058_50581601_93_dialog_content = "The staff said they'd give me a doll to keep me happy.",
  ui_story_5058_50581601_94_dialog_content = "And out of all those cute dolls they asked you to pick from, you chose that huge animal skeleton specimen they had on display!",
  ui_story_5058_50581601_95_dialog_content = "Hahaha! I really don't know what I was thinking at the time...",
  ui_story_5058_50581601_96_dialog_content = "I honestly can't believe it... My little Laurie has grown up so much.",
  ui_story_5058_50581601_97_dialog_content = "Mom, thanks for being there for me at the board meeting today.",
  ui_story_5058_50581601_98_dialog_content = "If I didn't have you there, I don't think I would've had the confidence to pull through.",
  ui_story_5058_50581601_99_dialog_content = "Don't be ridiculous—you're my daughter! What kind of mother wouldn't support her daughter, huh?!",
  ui_story_5058_50581601_100_dialog_content = "And I know that even if I were not there to stand by your side, you have it in you to achieve anything you set your mind to.",
  ui_story_5058_50581601_101_dialog_content = "Like how you fearlessly asked the Denuo Goddess for an antidote and saved me...",
  ui_story_5058_50581601_102_dialog_content = "If it weren't for you, I might never have been able to make peace with the Denuo Goddess.",
  ui_story_5058_50581601_103_dialog_content = "Indeed. Perhaps this entire experience was an opportunity bestowed unto us by the heavens, or perhaps by the Denuo Goddess herself...",
  ui_story_5058_50581601_104_dialog_content = "I was trapped in a long and painful nightmare—a dream in which I was forced to face my true self.",
  ui_story_5058_50581601_105_dialog_content = "That's when I suddenly realized that I hadn't been a good mother to you...",
  ui_story_5058_50581601_106_dialog_content = "I didn't tell you about your hometown and your loved ones, and I was even hampering your growth...",
  ui_story_5058_50581601_107_dialog_content = "Mom, don't say that about yourself!",
  ui_story_5058_50581601_108_dialog_content = "I'm the luckiest girl in the world, and you know why? Because I have two kind and beautiful moms!",
  ui_story_5058_50581601_109_dialog_content = "Whoa, whoa, whoa... If you two wanna have a mother-daughter heart-to-heart, that's perfectly okay, but why are you dragging me into this?",
  ui_story_5058_50581601_110_dialog_content = "I told the ladies I'd be right back! Those beautiful babies are waiting for me, for crying out loud!",
  ui_story_5058_50581601_111_dialog_content = "Of course I had to drag you along.",
  ui_story_5058_50581601_112_dialog_content = "Have you forgotten the promise me, you, and Coco?",
  ui_story_5058_50581601_113_dialog_content = "Promise? What promise?",
  ui_story_5058_50581601_114_dialog_content = "Oh, it's about to start... Three... two...",
  ui_story_5058_50581601_115_dialog_content = "One!",
  ui_story_5058_50581601_116_dialog_content = "<color=#e8d9bb>Whoosh—Bang!</color>",
  ui_story_5058_50581601_117_dialog_content = "It's...",
  ui_story_5058_50581601_118_dialog_content = "A fireworks display?",
  ui_story_5058_50581601_119_dialog_content = "<color=#e8d9bb>Whoosh—Bang, bang!</color>",
  ui_story_5058_50581601_120_dialog_content = "\"The fireworks zoomed into the night sky like fluttering butterflies...\"",
  ui_story_5058_50581601_121_dialog_content = "Are the fireworks in Lumopolis really that beautiful?",
  ui_story_5058_50581601_122_dialog_content = "I heard they're even more beautiful than butterflies!",
  ui_story_5058_50581601_123_dialog_content = "Mom, I wanna go to Lumopolis to watch the fireworks too!",
  ui_story_5058_50581601_124_dialog_content = "But Lumopolis is a long, long way away!",
  ui_story_5058_50581601_125_dialog_content = "What's there to be afraid of? Let's go and watch them together! I know we'll make it there one day!",
  ui_story_5058_50581601_126_dialog_content = "Really? Don't you two miss home?",
  ui_story_5058_50581601_127_dialog_content = "Wherever you are, Coco, that's where my home is.",
  ui_story_5058_50581601_128_dialog_content = "Hey! Are you tryna steal my mom, Cena?! Don't even think about it! Mom's all mine!",
  ui_story_5058_50581601_129_dialog_content = "I'm not even trying to say Coco's my mom though!",
  ui_story_5058_50581601_130_dialog_content = "Sh-She's... a lovely lady!",
  ui_story_5058_50581601_131_dialog_content = "Haha, it does sound fun to have a son as old as you!",
  ui_story_5058_50581601_132_dialog_content = "Ms. Coco! The loveliest lady I know!",
  ui_story_5058_50581601_133_dialog_content = "Luke, it's been so long since I've heard from you.",
  ui_story_5058_50581601_134_dialog_content = "\"You'll never guess where I'm working now!\"",
  ui_story_5058_50581601_X134_dialog_content = "\"I'm working at Denuo Valley Resort—the place you mentioned in your letter!\"",
  ui_story_5058_50581601_135_dialog_content = "If I were to tell you that Denuo Valley is the mysterious hometown I mentioned to you before, how shocked would you be?",
  ui_story_5058_50581601_136_dialog_content = "\"But I have something even more shocking to tell you...\"",
  ui_story_5058_50581601_X136_dialog_content = "\"I saw the Denuo Goddess!\"",
  ui_story_5058_50581601_137_dialog_content = "And that's right, I MADE IT OUT ALIVE! I know what you're thinking right now, \"Why did he write that he's still alive in all caps?\"",
  ui_story_5058_50581601_138_dialog_content = "Unfortunately, I can't fit all of the details into a single letter...",
  ui_story_5058_50581601_139_dialog_content = "If you have time, you simply have to come visit me at the resort. I'll be waiting for you, and ready to share all of my experiences since returning to my hometown.",
  ui_story_5058_50581601_140_dialog_content = "\"Every night before I close my eyes to sleep, I look forward to what tomorrow might bring. It feels...\"",
  ui_story_5058_50581601_X140_dialog_content = "<size=45>\"Awesome!\"</size>"
}
return config
